use clap::{Parser, ValueEnum};
use serde_json::json;
use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

mod parser;
mod analyzer;

use parser::NixParser;
use analyzer::DeadCodeAnalyzer;

#[derive(Parser, Debug)]
#[command(name = "deadnix")]
#[command(about = "Find dead code in .nix files", long_about = None)]
struct Args {
    /// .nix files, or directories with .nix files inside
    #[arg(default_value = ".")]
    file_paths: Vec<PathBuf>,

    /// Don't check lambda parameter arguments
    #[arg(short = 'l', long)]
    no_lambda_arg: bool,

    /// Don't check lambda attrset pattern names (don't break nixpkgs callPackage)
    #[arg(short = 'L', long)]
    no_lambda_pattern_names: bool,

    /// Don't check any bindings that start with a _
    #[arg(short = '_', long)]
    no_underscore: bool,

    /// Warn if bindings are referenced that start with '_'
    #[arg(short = 'W', long)]
    warn_used_underscore: bool,

    /// Don't print dead code report
    #[arg(short = 'q', long)]
    quiet: bool,

    /// Remove unused code and write to source file
    #[arg(short = 'e', long)]
    edit: bool,

    /// Recurse into hidden subdirectories and process hidden .*.nix files
    #[arg(short = 'h', long)]
    hidden: bool,

    /// Exit with 1 if unused code has been found
    #[arg(short = 'f', long)]
    fail: bool,

    /// Output format to use
    #[arg(short = 'o', long, value_name = "OUTPUT_FORMAT", default_value = "human-readable")]
    output_format: OutputFormat,

    /// Files to exclude from analysis
    #[arg(long)]
    exclude: Vec<PathBuf>,

    /// Print version
    #[arg(short = 'V', long)]
    version: bool,
}

#[derive(Debug, Clone, ValueEnum)]
enum OutputFormat {
    #[value(name = "human-readable")]
    HumanReadable,
    #[value(name = "json")]
    Json,
}

fn main() {
    let args = Args::parse();

    if args.version {
        println!("deadnix 1.3.1");
        return;
    }

    let exclude_set: HashSet<PathBuf> = args.exclude.iter().cloned().collect();
    let mut all_issues = Vec::new();
    let mut has_issues = false;

    for file_path in &args.file_paths {
        let paths = collect_nix_files(file_path, args.hidden, &exclude_set);

        for path in paths {
            match analyze_file(&path, &args) {
                Ok((issues, has_dead_code)) => {
                    all_issues.push((path.clone(), issues));
                    if has_dead_code {
                        has_issues = true;
                    }
                }
                Err(e) => {
                    eprintln!("Error analyzing {}: {}", path.display(), e);
                }
            }
        }
    }

    if !args.quiet {
        match args.output_format {
            OutputFormat::HumanReadable => {
                output_human_readable(&all_issues);
            }
            OutputFormat::Json => {
                output_json(&all_issues);
            }
        }
    }

    if args.fail && has_issues {
        std::process::exit(1);
    }
}

fn collect_nix_files(
    path: &Path,
    hidden: bool,
    exclude: &HashSet<PathBuf>,
) -> Vec<PathBuf> {
    let mut files = Vec::new();

    if path.is_file() {
        if path.extension().map(|e| e == "nix").unwrap_or(false) {
            files.push(path.to_path_buf());
        }
    } else if path.is_dir() {
        for entry in WalkDir::new(path)
            .into_iter()
            .filter_map(|e| e.ok())
        {
            let path = entry.path();

            if !hidden && path.components().any(|c| {
                if let std::path::Component::Normal(name) = c {
                    name.to_string_lossy().starts_with('.')
                } else {
                    false
                }
            }) {
                continue;
            }

            if exclude.contains(path) {
                continue;
            }

            if path.is_file() {
                let file_name = path.file_name().map(|n| n.to_string_lossy());
                if let Some(name) = file_name {
                    if name.ends_with(".nix") || (hidden && name.ends_with(".nix")) {
                        files.push(path.to_path_buf());
                    }
                }
            }
        }
    }

    files
}

fn analyze_file(path: &Path, args: &Args) -> Result<(Vec<Issue>, bool), String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Failed to read file: {}", e))?;

    let parser = NixParser::new(&content);
    let ast = parser.parse()?;

    let config = analyzer::AnalysisConfig {
        check_lambda_args: !args.no_lambda_arg,
        check_lambda_pattern_names: !args.no_lambda_pattern_names,
        check_underscore: !args.no_underscore,
        warn_used_underscore: args.warn_used_underscore,
    };

    let analyzer = DeadCodeAnalyzer::new(config);
    let issues = analyzer.analyze(&ast, &content)?;
    let has_issues = !issues.is_empty();

    Ok((issues, has_issues))
}

#[derive(Debug, Clone)]
struct Issue {
    line: usize,
    column: usize,
    end_column: usize,
    message: String,
}

fn output_human_readable(all_issues: &[(PathBuf, Vec<Issue>)]) {
    let mut has_output = false;

    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        has_output = true;

        if !has_output {
            continue;
        }

        // Print issues with formatting
        for issue in issues {
            println!("{}: {} ({}:{})", 
                path.display(),
                issue.message,
                issue.line,
                issue.column
            );
        }
    }

    if has_output {
        eprintln!("\u{1b}[33mWarning:\u{1b}[0m Unused declarations were found.");
    }
}

fn output_json(all_issues: &[(PathBuf, Vec<Issue>)]) {
    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        let results: Vec<_> = issues.iter().map(|issue| {
            json!({
                "line": issue.line,
                "column": issue.column,
                "endColumn": issue.end_column,
                "message": issue.message,
            })
        }).collect();

        let output = json!({
            "file": path.to_string_lossy(),
            "results": results,
        });

        println!("{}", output.to_string());
    }
}
