    column: usize,
    end_column: usize,
    message: String,
}

fn output_human_readable(all_issues: &[(PathBuf, Vec<Issue>)]) {
    let mut has_output = false;

    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        has_output = true;

        if !has_output {
            continue;
        }

        // Print issues with formatting
        for issue in issues {
            println!("{}: {} ({}:{})", 
                path.display(),
                issue.message,
                issue.line,
                issue.column
            );
        }
    }

    if has_output {
        eprintln!("\u{1b}[33mWarning:\u{1b}[0m Unused declarations were found.");
    }
}

fn output_json(all_issues: &[(PathBuf, Vec<Issue>)]) {
    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        let results: Vec<_> = issues.iter().map(|issue| {
            json!({
                "line": issue.line,
                "column": issue.column,
                "endColumn": issue.end_column,
                "message": issue.message,
            })
        }).collect();

        let output = json!({
            "file": path.to_string_lossy(),
            "results": results,
        });

        println!("{}", output.to_string());
    }
}
