                                Token::Integer(i)
                            } else if let Ok(f) = num_str.parse::<f64>() {
                                Token::Float(f)
                            } else {
                                Token::Minus
                            }
                        } else {
                            self.advance();
                            Token::Minus
                        }
                    }
                    '*' => {
                        self.advance();
                        Token::Star
                    }
                    '/' => {
                        self.advance();
                        Token::Slash
                    }
                    '|' => {
                        self.advance();
                        Token::Pipe
                    }
                    '&' => {
                        self.advance();
                        Token::Ampersand
                    }
                    '"' => {
                        let s = self.read_string();
                        Token::String(s)
                    }
                    _ if ch.is_alphabetic() || ch == '_' => {
                        let ident = self.read_identifier();
                        match ident.as_str() {
                            "let" => Token::Let,
                            "in" => Token::In,
                            "if" => Token::If,
                            "then" => Token::Then,
                            "else" => Token::Else,
                            "inherit" => Token::Inherit,
                            "rec" => Token::Rec,
                            "with" => Token::With,
                            "assert" => Token::Assert,
                            _ => Token::Identifier(ident),
                        }
                    }
                    _ if ch.is_numeric() => {
                        let mut num_str = String::new();
                        while let Some(ch) = self.current_char() {
                            if ch.is_numeric() || ch == '.' {
                                num_str.push(ch);
                                self.advance();
                            } else {
