use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // Literals
    Identifier(String),
    String(String),
    Integer(i64),
    Float(f64),

    // Keywords
    Let,
    In,
    If,
    Then,
    Else,
    Inherit,
    Rec,
    With,
    Assert,

    // Operators
    Eq,           // =
    Colon,        // :
    Semicolon,    // ;
    Dot,          // .
    Comma,        // ,
    Question,     // ?
    At,           // @
    Ellipsis,     // ...
    Plus,         // +
    Minus,        // -
    Star,         // *
    Slash,        // /
    Pipe,         // |
    Ampersand,    // &

    // Brackets
    LeftParen,    // (
    RightParen,   // )
    LeftBrace,    // {
    RightBrace,   // }
    LeftBracket,  // [
    RightBracket, // ]

    // String interpolation
    StringInterp,
    StringInterpEnd,

    Eof,
}

#[derive(Debug, Clone)]
pub struct Span {
    pub start: usize,
    pub end: usize,
    pub line: usize,
    pub column: usize,
}

#[derive(Debug, Clone)]
pub struct TokenWithSpan {
    pub token: Token,
    pub span: Span,
}

pub struct Lexer {
    input: Vec<char>,
    position: usize,
    line: usize,
    column: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            position: 0,
            line: 1,
            column: 1,
        }
    }

    fn current_char(&self) -> Option<char> {
        if self.position < self.input.len() {
            Some(self.input[self.position])
        } else {
            None
        }
    }

    fn peek_char(&self, offset: usize) -> Option<char> {
        if self.position + offset < self.input.len() {
            Some(self.input[self.position + offset])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        if self.position < self.input.len() {
            if self.input[self.position] == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
            self.position += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else if ch == '#' {
                // Comment - skip to end of line
                while let Some(ch) = self.current_char() {
                    if ch == '\n' {
                        break;
                    }
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn read_string(&mut self) -> String {
        self.advance(); // Skip opening quote
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch == '"' {
                self.advance();
                break;
            } else if ch == '\\' {
                self.advance();
                if let Some(next) = self.current_char() {
                    result.push(next);
                    self.advance();
                }
            } else {
                result.push(ch);
                self.advance();
            }
        }
        result
    }

    pub fn next_token(&mut self) -> TokenWithSpan {
        self.skip_whitespace();

        let line = self.line;
        let column = self.column;
        let start = self.position;

        let token = match self.current_char() {
            None => Token::Eof,
            Some(ch) => {
                match ch {
                    '(' => {
                        self.advance();
                        Token::LeftParen
                    }
                    ')' => {
                        self.advance();
                        Token::RightParen
                    }
                    '{' => {
                        self.advance();
                        Token::LeftBrace
                    }
                    '}' => {
                        self.advance();
                        Token::RightBrace
                    }
                    '[' => {
                        self.advance();
                        Token::LeftBracket
                    }
                    ']' => {
                        self.advance();
                        Token::RightBracket
                    }
                    '=' => {
                        self.advance();
                        Token::Eq
                    }
                    ':' => {
                        self.advance();
                        Token::Colon
                    }
                    ';' => {
                        self.advance();
                        Token::Semicolon
                    }
                    '.' => {
                        if self.peek_char(1) == Some('.') && self.peek_char(2) == Some('.') {
                            self.advance();
                            self.advance();
                            self.advance();
                            Token::Ellipsis
                        } else {
                            self.advance();
                            Token::Dot
                        }
                    }
                    ',' => {
                        self.advance();
                        Token::Comma
                    }
                    '?' => {
                        self.advance();
                        Token::Question
                    }
                    '@' => {
                        self.advance();
                        Token::At
                    }
                    '+' => {
                        self.advance();
                        Token::Plus
                    }
                    '-' => {
                        if self.peek_char(1).map(|c| c.is_numeric()).unwrap_or(false) {
                            let num_str = format!("-{}", self.read_identifier());
                            if let Ok(i) = num_str.parse::<i64>() {
                                Token::Integer(i)
                            } else if let Ok(f) = num_str.parse::<f64>() {
                                Token::Float(f)
                            } else {
                                Token::Minus
                            }
                        } else {
                            self.advance();
                            Token::Minus
                        }
                    }
                    '*' => {
                        self.advance();
                        Token::Star
                    }
                    '/' => {
                        self.advance();
                        Token::Slash
                    }
                    '|' => {
                        self.advance();
                        Token::Pipe
                    }
                    '&' => {
                        self.advance();
                        Token::Ampersand
                    }
                    '"' => {
                        let s = self.read_string();
                        Token::String(s)
                    }
                    _ if ch.is_alphabetic() || ch == '_' => {
                        let ident = self.read_identifier();
                        match ident.as_str() {
                            "let" => Token::Let,
                            "in" => Token::In,
                            "if" => Token::If,
                            "then" => Token::Then,
                            "else" => Token::Else,
                            "inherit" => Token::Inherit,
                            "rec" => Token::Rec,
                            "with" => Token::With,
                            "assert" => Token::Assert,
                            _ => Token::Identifier(ident),
                        }
                    }
                    _ if ch.is_numeric() => {
                        let mut num_str = String::new();
                        while let Some(ch) = self.current_char() {
                            if ch.is_numeric() || ch == '.' {
                                num_str.push(ch);
                                self.advance();
                            } else {
                                break;
                            }
                        }
                        if num_str.contains('.') {
                            Token::Float(num_str.parse().unwrap_or(0.0))
                        } else {
                            Token::Integer(num_str.parse().unwrap_or(0))
                        }
                    }
                    _ => {
                        self.advance();
                        Token::Identifier(ch.to_string())
                    }
                }
            }
        };

        TokenWithSpan {
            token,
            span: Span {
                start,
                end: self.position,
                line,
                column,
            },
        }
    }
}

