use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

mod parser;
mod analyzer;

use parser::NixParser;
use analyzer::DeadCodeAnalyzer;

#[derive(Debug, Clone)]
struct Args {
    file_paths: Vec<PathBuf>,
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
    warn_used_underscore: bool,
    quiet: bool,
    edit: bool,
    hidden: bool,
    fail: bool,
    output_format: OutputFormat,
    exclude: Vec<PathBuf>,
    version: bool,
}

#[derive(Debug, Clone)]
enum OutputFormat {
    HumanReadable,
    Json,
}

fn parse_args() -> Args {
    let mut args = Args {
        file_paths: vec![],
        no_lambda_arg: false,
        no_lambda_pattern_names: false,
        no_underscore: false,
        warn_used_underscore: false,
        quiet: false,
        edit: false,
        hidden: false,
        fail: false,
        output_format: OutputFormat::HumanReadable,
        exclude: vec![],
        version: false,
    };

    let cli_args: Vec<String> = env::args().collect();
    let mut i = 1;

    while i < cli_args.len() {
        let arg = &cli_args[i];
        match arg.as_str() {
            "-l" | "--no-lambda-arg" => args.no_lambda_arg = true,
            "-L" | "--no-lambda-pattern-names" => args.no_lambda_pattern_names = true,
            "-_" | "--no-underscore" => args.no_underscore = true,
            "-W" | "--warn-used-underscore" => args.warn_used_underscore = true,
            "-q" | "--quiet" => args.quiet = true,
            "-e" | "--edit" => args.edit = true,
            "-h" | "--hidden" => args.hidden = true,
            "-f" | "--fail" => args.fail = true,
            "-V" | "--version" => args.version = true,
            "--help" => {
                print_help();
                process::exit(0);
            }
            "-o" | "--output-format" => {
                i += 1;
                if i < cli_args.len() {
                    args.output_format = match cli_args[i].as_str() {
                        "json" => OutputFormat::Json,
                        "human-readable" => OutputFormat::HumanReadable,
                        _ => OutputFormat::HumanReadable,
                    };
                }
            }
            "--exclude" => {
                i += 1;
