            results.push_str(&format!(
                r#"{{"line":{},"column":{},"endColumn":{},"message":"{}"}}"#,
                issue.line,
                issue.column,
                issue.end_column,
                escape_json_string(&issue.message)
            ));
        }
        results.push(']');

        let output = format!(
            r#"{{"file":"{}","results":{}}}"#,
            escape_json_string(&path.to_string_lossy()),
            results
        );

        println!("{}", output);
    }
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}
