}

fn main() {
    let args = parse_args();

    if args.version {
        println!("deadnix 1.3.1");
        return;
    }

    let exclude_set: HashSet<PathBuf> = args.exclude.iter().cloned().collect();
    let mut all_issues = Vec::new();
    let mut has_issues = false;

    for file_path in &args.file_paths {
        let paths = collect_nix_files(file_path, args.hidden, &exclude_set);

        for path in paths {
            match analyze_file(&path, &args) {
                Ok((issues, has_dead_code)) => {
                    all_issues.push((path.clone(), issues));
                    if has_dead_code {
                        has_issues = true;
                    }
                }
                Err(e) => {
                    eprintln!("Error analyzing {}: {}", path.display(), e);
                }
            }
        }
    }

    if !args.quiet {
        match args.output_format {
            OutputFormat::HumanReadable => {
                output_human_readable(&all_issues);
            }
            OutputFormat::Json => {
                output_json(&all_issues);
            }
        }
    }

    if args.fail && has_issues {
        process::exit(1);
    }
}

fn collect_nix_files(
    path: &Path,
    hidden: bool,
    exclude: &HashSet<PathBuf>,
) -> Vec<PathBuf> {
    let mut files = Vec::new();

    if path.is_file() {
        if path.extension().map(|e| e == "nix").unwrap_or(false) {
            files.push(path.to_path_buf());
        }
    } else if path.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let path = entry.path();

                if exclude.contains(&path) {
                    continue;
                }

                if path.is_file() {
                    let file_name = path.file_name().map(|n| n.to_string_lossy());
                    if let Some(name) = file_name {
                        if name.ends_with(".nix") {
                            files.push(path);
                        }
                    }
                } else if path.is_dir() && hidden {
                    files.extend(collect_nix_files(&path, hidden, exclude));
                } else if path.is_dir() {
                    let dir_name = path.file_name().map(|n| n.to_string_lossy());
                    if let Some(name) = dir_name {
                        if !name.starts_with('.') {
                            files.extend(collect_nix_files(&path, hidden, exclude));
                        }
                    }
                }
            }
        }
    }

    files
}

fn analyze_file(path: &Path, args: &Args) -> Result<(Vec<Issue>, bool), String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Failed to read file: {}", e))?;

    let parser = NixParser::new(&content);
    let ast = parser.parse()?;

    let config = analyzer::AnalysisConfig {
        check_lambda_args: !args.no_lambda_arg,
        check_lambda_pattern_names: !args.no_lambda_pattern_names,
        check_underscore: !args.no_underscore,
        warn_used_underscore: args.warn_used_underscore,
    };

    let analyzer = DeadCodeAnalyzer::new(config);
    let issues = analyzer.analyze(&ast, &content)?;
    let has_issues = !issues.is_empty();

    Ok((issues, has_issues))
}

fn output_human_readable(all_issues: &[(PathBuf, Vec<Issue>)]) {
    let mut has_output = false;

    for (_, issues) in all_issues {
        if !issues.is_empty() {
            has_output = true;
            break;
        }
    }

    if !has_output {
        return;
    }

    eprintln!("\u{1b}[33mWarning:\u{1b}[0m Unused declarations were found.");

    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        for issue in issues {
            println!("{}: {} ({}:{})", 
                path.display(),
                issue.message,
                issue.line,
                issue.column
            );
        }
    }
}

fn output_json(all_issues: &[(PathBuf, Vec<Issue>)]) {
    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        let mut results = String::from("[");
        for (i, issue) in issues.iter().enumerate() {
            if i > 0 {
                results.push(',');
