#[derive(Debug, Clone, PartialEq)]
pub enum Token {
    // Literals
    Identifier(String),
    String(String),
    Integer(i64),
    Float(f64),

    // Keywords
    Let,
    In,
    If,
    Then,
    Else,
    Inherit,
    Rec,
    With,
    Assert,

    // Operators
    Eq,           // =
    Colon,        // :
    Semicolon,    // ;
    Dot,          // .
    Comma,        // ,
    Question,     // ?
    At,           // @
    Ellipsis,     // ...
    Plus,         // +
    Minus,        // -
    Star,         // *
    Slash,        // /
    Pipe,         // |
    Ampersand,    // &

    // Brackets
    LeftParen,    // (
    RightParen,   // )
    LeftBrace,    // {
    RightBrace,   // }
    LeftBracket,  // [
    RightBracket, // ]

    Eof,
}

#[derive(Debug, Clone)]
pub struct Span {
    pub start: usize,
    pub end: usize,
    pub line: usize,
    pub column: usize,
}

#[derive(Debug, Clone)]
pub struct TokenWithSpan {
    pub token: Token,
    pub span: Span,
}

pub struct Lexer {
    input: Vec<char>,
    position: usize,
    line: usize,
    column: usize,
}

impl Lexer {
    pub fn new(input: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            position: 0,
            line: 1,
            column: 1,
        }
    }

    fn current_char(&self) -> Option<char> {
        if self.position < self.input.len() {
            Some(self.input[self.position])
        } else {
            None
        }
    }

    fn peek_char(&self, offset: usize) -> Option<char> {
        if self.position + offset < self.input.len() {
            Some(self.input[self.position + offset])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        if self.position < self.input.len() {
            if self.input[self.position] == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
            self.position += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else if ch == '#' {
                // Comment - skip to end of line
                while let Some(ch) = self.current_char() {
                    if ch == '\n' {
                        break;
                    }
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn read_string(&mut self) -> String {
        self.advance(); // Skip opening quote
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch == '"' {
                self.advance();
                break;
            } else if ch == '\\' {
                self.advance();
                if let Some(next) = self.current_char() {
                    result.push(next);
                    self.advance();
                }
            } else {
                result.push(ch);
                self.advance();
            }
        }
        result
    }

    pub fn next_token(&mut self) -> TokenWithSpan {
        self.skip_whitespace();

        let line = self.line;
        let column = self.column;
        let start = self.position;

        let token = match self.current_char() {
            None => Token::Eof,
            Some(ch) => {
                match ch {
                    '(' => {
                        self.advance();
                        Token::LeftParen
                    }
                    ')' => {
                        self.advance();
                        Token::RightParen
                    }
                    '{' => {
                        self.advance();
                        Token::LeftBrace
                    }
                    '}' => {
                        self.advance();
                        Token::RightBrace
                    }
                    '[' => {
                        self.advance();
                        Token::LeftBracket
                    }
                    ']' => {
                        self.advance();
                        Token::RightBracket
                    }
                    '=' => {
                        self.advance();
                        Token::Eq
                    }
                    ':' => {
                        self.advance();
                        Token::Colon
                    }
                    ';' => {
                        self.advance();
                        Token::Semicolon
                    }
                    '.' => {
                        if self.peek_char(1) == Some('.') && self.peek_char(2) == Some('.') {
                            self.advance();
                            self.advance();
                            self.advance();
                            Token::Ellipsis
                        } else {
                            self.advance();
                            Token::Dot
                        }
                    }
                    ',' => {
                        self.advance();
                        Token::Comma
                    }
                    '?' => {
                        self.advance();
                        Token::Question
                    }
                    '@' => {
                        self.advance();
                        Token::At
                    }
                    '+' => {
                        self.advance();
                        Token::Plus
                    }
                    '-' => {
                        self.advance();
                        Token::Minus
                    }
                    '*' => {
                        self.advance();
                        Token::Star
                    }
                    '/' => {
                        self.advance();
                        Token::Slash
                    }
                    '|' => {
                        self.advance();
                        Token::Pipe
                    }
                    '&' => {
                        self.advance();
                        Token::Ampersand
                    }
                    '"' => {
                        let s = self.read_string();
                        Token::String(s)
                    }
                    _ if ch.is_alphabetic() || ch == '_' => {
                        let ident = self.read_identifier();
                        match ident.as_str() {
                            "let" => Token::Let,
                            "in" => Token::In,
                            "if" => Token::If,
                            "then" => Token::Then,
                            "else" => Token::Else,
                            "inherit" => Token::Inherit,
                            "rec" => Token::Rec,
                            "with" => Token::With,
                            "assert" => Token::Assert,
                            _ => Token::Identifier(ident),
                        }
                    }
                    _ if ch.is_numeric() => {
                        let mut num_str = String::new();
                        while let Some(ch) = self.current_char() {
                            if ch.is_numeric() || ch == '.' {
                                num_str.push(ch);
                                self.advance();
                            } else {
                                break;
                            }
                        }
                        if num_str.contains('.') {
                            Token::Float(num_str.parse().unwrap_or(0.0))
                        } else {
                            Token::Integer(num_str.parse().unwrap_or(0))
                        }
                    }
                    _ => {
                        self.advance();
                        Token::Identifier(ch.to_string())
                    }
                }
            }
        };

        TokenWithSpan {
            token,
            span: Span {
                start,
                end: self.position,
                line,
                column,
            },
        }
    }
}

#[derive(Debug, Clone)]
pub enum Expr {
    Identifier(String),
    String(String),
    Integer(i64),
    Float(f64),
    AttrSet {
        recursive: bool,
        attrs: Vec<(String, Expr)>,
    },
    List(Vec<Expr>),
    Lambda {
        param: LambdaParam,
        body: Box<Expr>,
    },
    Let {
        bindings: Vec<Binding>,
        body: Box<Expr>,
    },
    If {
        cond: Box<Expr>,
        then_expr: Box<Expr>,
        else_expr: Box<Expr>,
    },
    Apply {
        func: Box<Expr>,
        arg: Box<Expr>,
    },
    BinOp {
        op: String,
        left: Box<Expr>,
        right: Box<Expr>,
    },
    AttrAccess {
        object: Box<Expr>,
        attr: String,
    },
    With {
        env: Box<Expr>,
        body: Box<Expr>,
    },
    Assert {
        cond: Box<Expr>,
        body: Box<Expr>,
    },
    Inherit {
        from: Option<Box<Expr>>,
        attrs: Vec<String>,
    },
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub name: String,
    pub value: Expr,
    pub line: usize,
    pub column: usize,
}

#[derive(Debug, Clone)]
pub enum LambdaParam {
    Simple(String),
    AttrSet {
        patterns: Vec<AttrPattern>,
        name: Option<String>,
        ellipsis: bool,
    },
}

#[derive(Debug, Clone)]
pub struct AttrPattern {
    pub name: String,
    pub default: Option<Box<Expr>>,
}

pub struct NixParser {
    content: String,
}

impl NixParser {
    pub fn new(input: &str) -> Self {
        NixParser {
            content: input.to_string(),
        }
    }

    pub fn parse(&self) -> Result<Expr, String> {
        let mut lexer = Lexer::new(&self.content);
        Parser::new(&mut lexer).parse_expr()
    }
}

struct Parser<'a> {
    lexer: &'a mut Lexer,
    current: TokenWithSpan,
}

impl<'a> Parser<'a> {
    fn new(lexer: &'a mut Lexer) -> Self {
        let current = lexer.next_token();
        Parser { lexer, current }
    }

    fn advance(&mut self) -> TokenWithSpan {
        let current = lexer.next_token();
        let old = self.current.clone();
        self.current = current;
        old
    }

    fn expect(&mut self, expected: Token) -> Result<(), String> {
        if std::mem::discriminant(&self.current.token) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            Err(format!("Expected {:?}, got {:?}", expected, self.current.token))
        }
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        self.parse_and()
    }

    fn parse_and(&mut self) -> Result<Expr, String> {
        self.parse_comparison()
    }

    fn parse_comparison(&mut self) -> Result<Expr, String> {
        self.parse_additive()
    }

    fn parse_additive(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_multiplicative()?;

        while matches!(self.current.token, Token::Plus | Token::Minus) {
            let op = match &self.current.token {
                Token::Plus => "+".to_string(),
                Token::Minus => "-".to_string(),
                _ => unreachable!(),
            };
            self.advance();
            let right = self.parse_multiplicative()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_postfix()?;

        while matches!(self.current.token, Token::Star | Token::Slash) {
            let op = match &self.current.token {
                Token::Star => "*".to_string(),
                Token::Slash => "/".to_string(),
                _ => unreachable!(),
            };
            self.advance();
            let right = self.parse_postfix()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_postfix(&mut self) -> Result<Expr, String> {
        let mut expr = self.parse_primary()?;

        loop {
            match &self.current.token {
                Token::Dot => {
                    self.advance();
                    if let Token::Identifier(attr) = &self.current.token {
                        let attr_name = attr.clone();
                        self.advance();
                        expr = Expr::AttrAccess {
                            object: Box::new(expr),
                            attr: attr_name,
                        };
                    } else {
                        return Err("Expected identifier after .".to_string());
                    }
                }
                _ => break,
            }
        }

        Ok(expr)
    }

    fn parse_primary(&mut self) -> Result<Expr, String> {
        match &self.current.token {
            Token::Let => {
                self.advance();
                self.parse_let()
            }
            Token::If => {
                self.advance();
                self.parse_if()
            }
            Token::With => {
                self.advance();
                self.parse_with()
            }
            Token::Assert => {
                self.advance();
                self.parse_assert()
            }
            Token::Inherit => {
                self.advance();
                self.parse_inherit()
            }
            Token::LeftBrace => {
                self.advance();
                self.parse_attr_set()
            }
            Token::LeftBracket => {
                self.advance();
                self.parse_list()
            }
            Token::LeftParen => {
                self.advance();
                let expr = self.parse_expr()?;
                self.expect(Token::RightParen)?;
                Ok(expr)
            }
            Token::Identifier(name) => {
                let id = name.clone();
                self.advance();

                // Check if this is a lambda
                if matches!(self.current.token, Token::Colon) {
                    self.advance();
                    let body = self.parse_expr()?;
                    Ok(Expr::Lambda {
                        param: LambdaParam::Simple(id),
                        body: Box::new(body),
                    })
                } else {
                    Ok(Expr::Identifier(id))
                }
            }
            Token::String(s) => {
                let string = s.clone();
                self.advance();
                Ok(Expr::String(string))
            }
            Token::Integer(i) => {
                let int = *i;
                self.advance();
                Ok(Expr::Integer(int))
            }
            Token::Float(f) => {
                let float = *f;
                self.advance();
                Ok(Expr::Float(float))
            }
            _ => Err(format!("Unexpected token: {:?}", self.current.token)),
        }
    }

    fn parse_let(&mut self) -> Result<Expr, String> {
        let mut bindings = Vec::new();

        while !matches!(self.current.token, Token::In) {
            if let Token::Identifier(name) = &self.current.token {
                let name = name.clone();
                let line = self.current.span.line;
                let column = self.current.span.column;
                self.advance();

                self.expect(Token::Eq)?;

                let value = self.parse_expr()?;
                self.expect(Token::Semicolon)?;

                bindings.push(Binding {
                    name,
                    value,
                    line,
                    column,
                });
            } else if matches!(self.current.token, Token::Inherit) {
                self.advance();
                let binding = self.parse_inherit_binding()?;
                if let Expr::Inherit { from, attrs } = binding {
                    for attr in attrs {
                        bindings.push(Binding {
                            name: attr.clone(),
                            value: Expr::Identifier(attr),
                            line: self.current.span.line,
                            column: self.current.span.column,
                        });
                    }
                }
            } else {
                return Err(format!("Expected identifier in let binding, got {:?}", self.current.token));
            }
        }

        self.expect(Token::In)?;
        let body = self.parse_expr()?;

        Ok(Expr::Let {
            bindings,
            body: Box::new(body),
        })
    }

    fn parse_if(&mut self) -> Result<Expr, String> {
        let cond = self.parse_expr()?;
        self.expect(Token::Then)?;
        let then_expr = self.parse_expr()?;
        self.expect(Token::Else)?;
        let else_expr = self.parse_expr()?;

        Ok(Expr::If {
            cond: Box::new(cond),
            then_expr: Box::new(then_expr),
            else_expr: Box::new(else_expr),
        })
    }

    fn parse_with(&mut self) -> Result<Expr, String> {
        let env = self.parse_expr()?;
        self.expect(Token::Semicolon)?;
        let body = self.parse_expr()?;

        Ok(Expr::With {
            env: Box::new(env),
            body: Box::new(body),
        })
    }

    fn parse_assert(&mut self) -> Result<Expr, String> {
        let cond = self.parse_expr()?;
        self.expect(Token::Semicolon)?;
        let body = self.parse_expr()?;

        Ok(Expr::Assert {
            cond: Box::new(cond),
            body: Box::new(body),
        })
    }

    fn parse_inherit(&mut self) -> Result<Expr, String> {
        let from = if matches!(self.current.token, Token::LeftParen) {
            self.advance();
            let expr = self.parse_expr()?;
            self.expect(Token::RightParen)?;
            Some(Box::new(expr))
        } else {
            None
        };

        let mut attrs = Vec::new();
        while let Token::Identifier(name) = &self.current.token {
            attrs.push(name.clone());
            self.advance();
        }

        Ok(Expr::Inherit { from, attrs })
    }

    fn parse_inherit_binding(&mut self) -> Result<Expr, String> {
        let from = if matches!(self.current.token, Token::LeftParen) {
            self.advance();
            let expr = self.parse_expr()?;
            self.expect(Token::RightParen)?;
            Some(Box::new(expr))
        } else {
            None
        };

        let mut attrs = Vec::new();
        while let Token::Identifier(name) = &self.current.token {
            attrs.push(name.clone());
            self.advance();
        }

        self.expect(Token::Semicolon)?;

        Ok(Expr::Inherit { from, attrs })
    }

    fn parse_attr_set(&mut self) -> Result<Expr, String> {
        let mut attrs = Vec::new();
        let recursive = matches!(self.current.token, Token::Rec);
        if recursive {
            self.advance();
        }

        while !matches!(self.current.token, Token::RightBrace) {
            if let Token::Identifier(name) = &self.current.token {
                let name = name.clone();
                self.advance();
                self.expect(Token::Eq)?;
                let value = self.parse_expr()?;
                attrs.push((name, value));
                if !matches!(self.current.token, Token::RightBrace) {
                    self.expect(Token::Semicolon)?;
                }
            } else {
                return Err(format!("Expected identifier in attrset, got {:?}", self.current.token));
            }
        }

        self.expect(Token::RightBrace)?;

        Ok(Expr::AttrSet {
            recursive,
            attrs,
        })
    }

    fn parse_list(&mut self) -> Result<Expr, String> {
        let mut items = Vec::new();

        while !matches!(self.current.token, Token::RightBracket) {
            items.push(self.parse_expr()?);
        }

        self.expect(Token::RightBracket)?;

        Ok(Expr::List(items))
    }
