                        let ident = self.read_identifier();
                        match ident.as_str() {
                            "let" => Token::Let,
                            "in" => Token::In,
                            "if" => Token::If,
                            "then" => Token::Then,
                            "else" => Token::Else,
                            "inherit" => Token::Inherit,
                            "rec" => Token::Rec,
                            "with" => Token::With,
                            "assert" => Token::Assert,
