            content: input.to_string(),
        }
    }

    pub fn parse(&self) -> Result<Expr, String> {
        let mut lexer = Lexer::new(&self.content);
        Parser::new(&mut lexer).parse_expr()
    }
}

struct Parser<'a> {
    lexer: &'a mut Lexer,
    current: TokenWithSpan,
}

impl<'a> Parser<'a> {
    fn new(lexer: &'a mut Lexer) -> Self {
        let current = lexer.next_token();
        Parser { lexer, current }
    }

    fn advance(&mut self) -> TokenWithSpan {
        let current = lexer.next_token();
        let old = self.current.clone();
        self.current = current;
        old
    }

    fn expect(&mut self, expected: Token) -> Result<(), String> {
        if std::mem::discriminant(&self.current.token) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            Err(format!("Expected {:?}, got {:?}", expected, self.current.token))
        }
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        self.parse_and()
    }

    fn parse_and(&mut self) -> Result<Expr, String> {
        self.parse_comparison()
    }

    fn parse_comparison(&mut self) -> Result<Expr, String> {
        self.parse_additive()
    }

    fn parse_additive(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_multiplicative()?;

        while matches!(self.current.token, Token::Plus | Token::Minus) {
            let op = match &self.current.token {
                Token::Plus => "+".to_string(),
                Token::Minus => "-".to_string(),
                _ => unreachable!(),
            };
            self.advance();
            let right = self.parse_multiplicative()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_postfix()?;

        while matches!(self.current.token, Token::Star | Token::Slash) {
            let op = match &self.current.token {
                Token::Star => "*".to_string(),
                Token::Slash => "/".to_string(),
                _ => unreachable!(),
            };
            self.advance();
            let right = self.parse_postfix()?;
            left = Expr::BinOp {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_postfix(&mut self) -> Result<Expr, String> {
        let mut expr = self.parse_primary()?;

        loop {
            match &self.current.token {
                Token::Dot => {
                    self.advance();
                    if let Token::Identifier(attr) = &self.current.token {
                        let attr_name = attr.clone();
                        self.advance();
                        expr = Expr::AttrAccess {
                            object: Box::new(expr),
                            attr: attr_name,
                        };
                    } else {
                        return Err("Expected identifier after .".to_string());
                    }
                }
                _ => break,
            }
        }

        Ok(expr)
    }

    fn parse_primary(&mut self) -> Result<Expr, String> {
        match &self.current.token {
            Token::Let => {
                self.advance();
                self.parse_let()
            }
            Token::If => {
                self.advance();
                self.parse_if()
            }
            Token::With => {
                self.advance();
                self.parse_with()
            }
            Token::Assert => {
                self.advance();
                self.parse_assert()
            }
            Token::Inherit => {
                self.advance();
                self.parse_inherit()
            }
            Token::LeftBrace => {
                self.advance();
                self.parse_attr_set()
            }
            Token::LeftBracket => {
                self.advance();
                self.parse_list()
            }
            Token::LeftParen => {
                self.advance();
                let expr = self.parse_expr()?;
                self.expect(Token::RightParen)?;
                Ok(expr)
            }
            Token::Identifier(name) => {
                let id = name.clone();
                self.advance();

                // Check if this is a lambda
                if matches!(self.current.token, Token::Colon) {
                    self.advance();
                    let body = self.parse_expr()?;
                    Ok(Expr::Lambda {
                        param: LambdaParam::Simple(id),
                        body: Box::new(body),
                    })
                } else {
                    Ok(Expr::Identifier(id))
                }
            }
            Token::String(s) => {
                let string = s.clone();
                self.advance();
                Ok(Expr::String(string))
            }
            Token::Integer(i) => {
                let int = *i;
                self.advance();
                Ok(Expr::Integer(int))
            }
            Token::Float(f) => {
                let float = *f;
                self.advance();
                Ok(Expr::Float(float))
            }
            _ => Err(format!("Unexpected token: {:?}", self.current.token)),
        }
    }

    fn parse_let(&mut self) -> Result<Expr, String> {
        let mut bindings = Vec::new();

        while !matches!(self.current.token, Token::In) {
            if let Token::Identifier(name) = &self.current.token {
                let name = name.clone();
                let line = self.current.span.line;
                let column = self.current.span.column;
                self.advance();

                self.expect(Token::Eq)?;

                let value = self.parse_expr()?;
                self.expect(Token::Semicolon)?;

                bindings.push(Binding {
                    name,
                    value,
                    line,
                    column,
                });
            } else if matches!(self.current.token, Token::Inherit) {
                self.advance();
                let binding = self.parse_inherit_binding()?;
                if let Expr::Inherit { from, attrs } = binding {
                    for attr in attrs {
                        bindings.push(Binding {
                            name: attr.clone(),
                            value: Expr::Identifier(attr),
                            line: self.current.span.line,
                            column: self.current.span.column,
                        });
                    }
                }
            } else {
                return Err(format!("Expected identifier in let binding, got {:?}", self.current.token));
            }
        }

        self.expect(Token::In)?;
        let body = self.parse_expr()?;

        Ok(Expr::Let {
            bindings,
            body: Box::new(body),
        })
    }

    fn parse_if(&mut self) -> Result<Expr, String> {
        let cond = self.parse_expr()?;
        self.expect(Token::Then)?;
        let then_expr = self.parse_expr()?;
        self.expect(Token::Else)?;
        let else_expr = self.parse_expr()?;

        Ok(Expr::If {
            cond: Box::new(cond),
            then_expr: Box::new(then_expr),
            else_expr: Box::new(else_expr),
        })
    }

    fn parse_with(&mut self) -> Result<Expr, String> {
        let env = self.parse_expr()?;
        self.expect(Token::Semicolon)?;
        let body = self.parse_expr()?;

        Ok(Expr::With {
            env: Box::new(env),
            body: Box::new(body),
        })
    }

    fn parse_assert(&mut self) -> Result<Expr, String> {
        let cond = self.parse_expr()?;
        self.expect(Token::Semicolon)?;
        let body = self.parse_expr()?;

        Ok(Expr::Assert {
            cond: Box::new(cond),
            body: Box::new(body),
        })
    }

    fn parse_inherit(&mut self) -> Result<Expr, String> {
        let from = if matches!(self.current.token, Token::LeftParen) {
            self.advance();
            let expr = self.parse_expr()?;
            self.expect(Token::RightParen)?;
            Some(Box::new(expr))
        } else {
            None
        };

        let mut attrs = Vec::new();
        while let Token::Identifier(name) = &self.current.token {
            attrs.push(name.clone());
            self.advance();
        }

        Ok(Expr::Inherit { from, attrs })
    }

    fn parse_inherit_binding(&mut self) -> Result<Expr, String> {
        let from = if matches!(self.current.token, Token::LeftParen) {
            self.advance();
            let expr = self.parse_expr()?;
            self.expect(Token::RightParen)?;
            Some(Box::new(expr))
        } else {
            None
        };

        let mut attrs = Vec::new();
        while let Token::Identifier(name) = &self.current.token {
            attrs.push(name.clone());
            self.advance();
        }

        self.expect(Token::Semicolon)?;

        Ok(Expr::Inherit { from, attrs })
    }

    fn parse_attr_set(&mut self) -> Result<Expr, String> {
        let mut attrs = Vec::new();
        let recursive = matches!(self.current.token, Token::Rec);
        if recursive {
            self.advance();
        }

        while !matches!(self.current.token, Token::RightBrace) {
            if let Token::Identifier(name) = &self.current.token {
                let name = name.clone();
                self.advance();
                self.expect(Token::Eq)?;
                let value = self.parse_expr()?;
                attrs.push((name, value));
                if !matches!(self.current.token, Token::RightBrace) {
                    self.expect(Token::Semicolon)?;
                }
            } else {
                return Err(format!("Expected identifier in attrset, got {:?}", self.current.token));
            }
        }

        self.expect(Token::RightBrace)?;

        Ok(Expr::AttrSet {
            recursive,
            attrs,
        })
    }

    fn parse_list(&mut self) -> Result<Expr, String> {
        let mut items = Vec::new();

        while !matches!(self.current.token, Token::RightBracket) {
            items.push(self.parse_expr()?);
        }

        self.expect(Token::RightBracket)?;

        Ok(Expr::List(items))
    }
}
