        }
    }

    fn advance(&mut self) {
        if self.position < self.input.len() {
            if self.input[self.position] == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
            self.position += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else if ch == '#' {
                // Comment - skip to end of line
                while let Some(ch) = self.current_char() {
                    if ch == '\n' {
                        break;
                    }
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn read_string(&mut self) -> String {
        self.advance(); // Skip opening quote
        let mut result = String::new();
        while let Some(ch) = self.current_char() {
            if ch == '"' {
                self.advance();
                break;
            } else if ch == '\\' {
                self.advance();
                if let Some(next) = self.current_char() {
                    result.push(next);
                    self.advance();
                }
            } else {
                result.push(ch);
                self.advance();
            }
        }
        result
    }

    pub fn next_token(&mut self) -> TokenWithSpan {
        self.skip_whitespace();

        let line = self.line;
        let column = self.column;
        let start = self.position;

        let token = match self.current_char() {
            None => Token::Eof,
            Some(ch) => {
                match ch {
                    '(' => {
                        self.advance();
                        Token::LeftParen
                    }
                    ')' => {
                        self.advance();
                        Token::RightParen
                    }
                    '{' => {
                        self.advance();
                        Token::LeftBrace
                    }
                    '}' => {
                        self.advance();
                        Token::RightBrace
                    }
                    '[' => {
                        self.advance();
                        Token::LeftBracket
                    }
                    ']' => {
                        self.advance();
                        Token::RightBracket
                    }
                    '=' => {
                        self.advance();
                        Token::Eq
                    }
                    ':' => {
                        self.advance();
                        Token::Colon
                    }
                    ';' => {
                        self.advance();
                        Token::Semicolon
                    }
                    '.' => {
                        if self.peek_char(1) == Some('.') && self.peek_char(2) == Some('.') {
                            self.advance();
                            self.advance();
                            self.advance();
                            Token::Ellipsis
                        } else {
                            self.advance();
                            Token::Dot
                        }
                    }
                    ',' => {
                        self.advance();
                        Token::Comma
                    }
                    '?' => {
                        self.advance();
                        Token::Question
                    }
                    '@' => {
                        self.advance();
                        Token::At
                    }
                    '+' => {
                        self.advance();
                        Token::Plus
                    }
                    '-' => {
                        self.advance();
                        Token::Minus
                    }
                    '*' => {
                        self.advance();
                        Token::Star
                    }
                    '/' => {
                        self.advance();
                        Token::Slash
                    }
                    '|' => {
                        self.advance();
                        Token::Pipe
                    }
                    '&' => {
                        self.advance();
                        Token::Ampersand
                    }
                    '"' => {
                        let s = self.read_string();
                        Token::String(s)
                    }
                    _ if ch.is_alphabetic() || ch == '_' => {
                        let ident = self.read_identifier();
                        match ident.as_str() {
                            "let" => Token::Let,
                            "in" => Token::In,
                            "if" => Token::If,
                            "then" => Token::Then,
                            "else" => Token::Else,
                            "inherit" => Token::Inherit,
                            "rec" => Token::Rec,
                            "with" => Token::With,
                            "assert" => Token::Assert,
                            _ => Token::Identifier(ident),
                        }
                    }
                    _ if ch.is_numeric() => {
                        let mut num_str = String::new();
                        while let Some(ch) = self.current_char() {
                            if ch.is_numeric() || ch == '.' {
                                num_str.push(ch);
                                self.advance();
                            } else {
                                break;
                            }
                        }
                        if num_str.contains('.') {
                            Token::Float(num_str.parse().unwrap_or(0.0))
                        } else {
                            Token::Integer(num_str.parse().unwrap_or(0))
                        }
                    }
                    _ => {
                        self.advance();
                        Token::Identifier(ch.to_string())
                    }
                }
            }
        };

        TokenWithSpan {
            token,
            span: Span {
                start,
                end: self.position,
                line,
                column,
            },
        }
    }
}

