#[derive(Debug, Clone)]
pub struct Binding {
    pub name: String,
    pub value: Expr,
    pub line: usize,
    pub column: usize,
}

#[derive(Debug, Clone)]
pub enum LambdaParam {
    Simple(String),
    AttrSet {
        patterns: Vec<AttrPattern>,
        name: Option<String>,
        ellipsis: bool,
    },
}

#[derive(Debug, Clone)]
pub struct AttrPattern {
    pub name: String,
