use crate::parser::{Expr, Binding, LambdaParam, AttrPattern};
use crate::Issue;
use std::collections::{HashMap, HashSet};

#[derive(Clone)]
pub struct AnalysisConfig {
    pub check_lambda_args: bool,
    pub check_lambda_pattern_names: bool,
    pub check_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct DeadCodeAnalyzer {
    config: AnalysisConfig,
}

impl DeadCodeAnalyzer {
    pub fn new(config: AnalysisConfig) -> Self {
        DeadCodeAnalyzer { config }
    }

    pub fn analyze(&self, ast: &Expr, _content: &str) -> Result<Vec<Issue>, String> {
        let mut context = AnalysisContext {
            scopes: vec![HashMap::new()],
            config: self.config.clone(),
            issues: Vec::new(),
        };

        self.analyze_expr(ast, &mut context);

        // Check unused bindings in final scope
        context.check_unused();

        Ok(context.issues)
    }

    fn analyze_expr(&self, expr: &Expr, ctx: &mut AnalysisContext) {
        match expr {
            Expr::Let { bindings, body } => {
                ctx.push_scope();

                // First pass: collect all bindings
                for binding in bindings {
                    if !ctx.config.check_underscore && binding.name.starts_with('_') {
                        ctx.use_identifier(&binding.name);
                    } else if !binding.name.starts_with('_') || ctx.config.check_underscore {
                        ctx.define_binding(&binding.name, binding.line, binding.column);
                    }
                }

                // Second pass: analyze values
                for binding in bindings {
                    self.analyze_expr(&binding.value, ctx);
                }

                self.analyze_expr(body, ctx);

                // Check for unused bindings
                ctx.check_unused();
                ctx.pop_scope();
            }
            Expr::Lambda { param, body } => {
                ctx.push_scope();

                match param {
                    LambdaParam::Simple(name) => {
                        if ctx.config.check_lambda_args {
                            ctx.define_binding(name, 0, 0);
                        }
                    }
                    LambdaParam::AttrSet {
                        patterns,
                        name,
                        ellipsis,
                    } => {
                        if let Some(n) = name {
                            if ctx.config.check_lambda_pattern_names {
                                ctx.define_binding(n, 0, 0);
                            }
                        }

                        for pattern in patterns {
                            if ctx.config.check_lambda_pattern_names {
                                ctx.define_binding(&pattern.name, 0, 0);
                            }
                            if let Some(default) = &pattern.default {
                                self.analyze_expr(default, ctx);
                            }
                        }
                    }
                }

                self.analyze_expr(body, ctx);
                ctx.check_unused();
                ctx.pop_scope();
            }
            Expr::If {
                cond,
                then_expr,
                else_expr,
            } => {
                self.analyze_expr(cond, ctx);
                self.analyze_expr(then_expr, ctx);
                self.analyze_expr(else_expr, ctx);
            }
            Expr::Apply { func, arg } => {
                self.analyze_expr(func, ctx);
                self.analyze_expr(arg, ctx);
            }
            Expr::BinOp { left, right, .. } => {
                self.analyze_expr(left, ctx);
                self.analyze_expr(right, ctx);
            }
            Expr::AttrAccess { object, attr } => {
                self.analyze_expr(object, ctx);
                ctx.use_identifier(attr);
            }
            Expr::With { env, body } => {
                self.analyze_expr(env, ctx);
                self.analyze_expr(body, ctx);
            }
            Expr::Assert { cond, body } => {
                self.analyze_expr(cond, ctx);
                self.analyze_expr(body, ctx);
            }
            Expr::AttrSet { attrs, .. } => {
                for (_, value) in attrs {
                    self.analyze_expr(value, ctx);
                }
            }
            Expr::List(items) => {
                for item in items {
                    self.analyze_expr(item, ctx);
                }
            }
            Expr::Identifier(name) => {
                ctx.use_identifier(name);
            }
            Expr::Inherit { from, attrs } => {
                if let Some(f) = from {
                    self.analyze_expr(f, ctx);
                }
                for attr in attrs {
                    ctx.use_identifier(attr);
                }
            }
            Expr::String(_) | Expr::Integer(_) | Expr::Float(_) => {}
        }
    }
}

struct AnalysisContext {
    scopes: Vec<HashMap<String, (usize, usize)>>,
    config: AnalysisConfig,
    issues: Vec<Issue>,
}

impl AnalysisContext {
    fn push_scope(&mut self) {
        self.scopes.push(HashMap::new());
    }

    fn pop_scope(&mut self) {
        self.scopes.pop();
    }

    fn define_binding(&mut self, name: &str, line: usize, column: usize) {
        if let Some(scope) = self.scopes.last_mut() {
            scope.insert(name.to_string(), (line, column));
        }
    }

    fn use_identifier(&mut self, name: &str) {
        // Mark as used in all scopes
        for scope in &mut self.scopes {
            if scope.contains_key(name) {
                scope.remove(name);
                break;
            }
        }
    }

    fn check_unused(&mut self) {
        if let Some(scope) = self.scopes.last() {
            for (name, (line, column)) in scope {
                let end_column = column + name.len();
                self.issues.push(Issue {
                    line: if *line > 0 { *line } else { 1 },
                    column: if *column > 0 { *column } else { 1 },
                    end_column,
                    message: format!("Unused let binding: {}", name),
                });
            }
        }
    }
}
