use crate::parser::Expr;
use crate::Issue;
use std::collections::{HashMap, HashSet};

#[derive(Clone)]
pub struct AnalysisConfig {
    pub check_lambda_args: bool,
    pub check_lambda_pattern_names: bool,
    pub check_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct DeadCodeAnalyzer {
    config: AnalysisConfig,
}

impl DeadCodeAnalyzer {
    pub fn new(config: AnalysisConfig) -> Self {
        DeadCodeAnalyzer { config }
    }

    pub fn analyze(&self, ast: &Expr, content: &str) -> Result<Vec<Issue>, String> {
        match ast {
            Expr::Program(program_content) => {
                self.analyze_content(program_content, &self.config)
            }
        }
    }

    fn analyze_content(&self, content: &str, config: &AnalysisConfig) -> Result<Vec<Issue>, String> {
        let mut issues = Vec::new();
        let lines: Vec<&str> = content.lines().collect();

        // First pass: collect all definitions and usages
        let mut definitions: HashMap<String, (usize, usize)> = HashMap::new();
        let mut usages: HashSet<String> = HashSet::new();

        // Parse the file to find definitions and usages
        for (line_idx, line) in lines.iter().enumerate() {
            let line_num = line_idx + 1;

            // Skip comments
            let trimmed = line.trim();
            if trimmed.starts_with('#') {
                continue;
            }

            // Find let bindings
            if line.contains(" = ") && !line.trim().starts_with("inherit") {
                if let Some(eq_pos) = line.find(" = ") {
                    let before_eq = &line[..eq_pos].trim_end();

                    // Extract identifier
                    let ident = before_eq.trim();
                    if is_valid_identifier(ident) && !ident.contains('{') && !ident.contains('[') {
                        let col = line.find(ident).unwrap_or(0) + 1;
                        if !ident.starts_with('_') || config.check_underscore {
                            definitions.insert(ident.to_string(), (line_num, col));
                        }
                    }
                }
            }

            // Find inherit statements
            if line.contains("inherit") {
                self.parse_inherit_line(line, line_num, &mut definitions, config);
            }

            // Find usages
            self.parse_usages(line, &mut usages, config);

            // Find lambda arguments
            if line.contains('@') && line.contains('{') {
                self.parse_lambda_args(line, line_num, &mut definitions, config);
            }
        }

        // Determine which definitions are unused
        for (name, (line_num, col)) in definitions.iter() {
            if !usages.contains(name) {
                let end_col = col + name.len();
                issues.push(Issue {
                    line: *line_num,
                    column: *col,
                    end_column: end_col,
                    message: format!("Unused let binding: {}", name),
                });
            }
        }

        Ok(issues)
    }

    fn parse_inherit_line(
        &self,
        line: &str,
        line_num: usize,
        definitions: &mut HashMap<String, (usize, usize)>,
        config: &AnalysisConfig,
    ) {
        // inherit (source) name1 name2;
        if let Some(paren_start) = line.find('(') {
            if let Some(paren_end) = line.find(')') {
                let after_paren = &line[paren_end + 1..];
                let inherit_names = after_paren.split_whitespace()
                    .filter(|s| !s.is_empty() && *s != ";");

                for name in inherit_names {
                    let clean_name = name.trim_end_matches(';');
                    if is_valid_identifier(clean_name) {
                        if !clean_name.starts_with('_') || config.check_underscore {
                            if let Some(col) = line.find(clean_name) {
                                definitions.insert(clean_name.to_string(), (line_num, col + 1));
                            }
                        }
                    }
                }
            }
        }
    }

    fn parse_usages(&self, line: &str, usages: &mut HashSet<String>, config: &AnalysisConfig) {
        // Extract all identifiers from the line
        let mut current_word = String::new();
        let mut prev_char = ' ';

        for ch in line.chars() {
            if ch.is_alphanumeric() || ch == '_' {
                current_word.push(ch);
            } else {
                if !current_word.is_empty() && is_valid_identifier(&current_word) {
                    if !current_word.starts_with('_') || config.warn_used_underscore {
                        usages.insert(current_word.clone());
                    }
                }
                current_word.clear();
            }
            prev_char = ch;
        }

        if !current_word.is_empty() && is_valid_identifier(&current_word) {
            if !current_word.starts_with('_') || config.warn_used_underscore {
                usages.insert(current_word);
            }
        }
    }

    fn parse_lambda_args(
        &self,
        line: &str,
        line_num: usize,
        definitions: &mut HashMap<String, (usize, usize)>,
        config: &AnalysisConfig,
    ) {
        // { arg1, arg2, ... }@name:
        if let Some(at_pos) = line.find('@') {
            if let Some(brace_start) = line.rfind('{') {
                if brace_start < at_pos {
                    if let Some(brace_end) = line.find('}') {
                        if brace_start < brace_end && brace_end < at_pos {
                            let args_str = &line[brace_start + 1..brace_end];
                            let args: Vec<&str> = args_str.split(',').collect();

                            for arg in args {
                                let arg_name = arg.trim().split('?').next().unwrap_or("").trim();
                                if !arg_name.is_empty() && arg_name != "..." && is_valid_identifier(arg_name) {
                                    if config.check_lambda_pattern_names && (!arg_name.starts_with('_') || config.check_underscore) {
                                        if let Some(col) = line.find(arg_name) {
                                            definitions.insert(arg_name.to_string(), (line_num, col + 1));
                                        }
                                    }
                                }
                            }

                            // Also add the name after @
                            let after_at = &line[at_pos + 1..];
                            let name = after_at.trim().split(':').next().unwrap_or("").trim();
                            if !name.is_empty() && is_valid_identifier(name) {
                                if config.check_lambda_pattern_names && (!name.starts_with('_') || config.check_underscore) {
                                    if let Some(col) = line.find(name) {
                                        definitions.insert(name.to_string(), (line_num, col + 1));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

fn is_valid_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '\'' )
}
