use std::collections::{HashMap, HashSet};
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

mod parser;
mod analyzer;

use analyzer::NixAnalyzer;

#[derive(Debug, Clone)]
struct Args {
    file_paths: Vec<PathBuf>,
    no_lambda_arg: bool,
    no_lambda_pattern_names: bool,
    no_underscore: bool,
    warn_used_underscore: bool,
    quiet: bool,
    edit: bool,
    hidden: bool,
    fail: bool,
    output_format: OutputFormat,
    exclude: Vec<PathBuf>,
    version: bool,
}

#[derive(Debug, Clone)]
enum OutputFormat {
    HumanReadable,
    Json,
}

fn parse_args() -> Args {
    let mut args = Args {
        file_paths: vec![],
        no_lambda_arg: false,
        no_lambda_pattern_names: false,
        no_underscore: false,
        warn_used_underscore: false,
        quiet: false,
        edit: false,
        hidden: false,
        fail: false,
        output_format: OutputFormat::HumanReadable,
        exclude: vec![],
        version: false,
    };

    let cli_args: Vec<String> = env::args().collect();
    let mut i = 1;

    while i < cli_args.len() {
        let arg = &cli_args[i];
        match arg.as_str() {
            "-l" | "--no-lambda-arg" => args.no_lambda_arg = true,
            "-L" | "--no-lambda-pattern-names" => args.no_lambda_pattern_names = true,
            "-_" | "--no-underscore" => args.no_underscore = true,
            "-W" | "--warn-used-underscore" => args.warn_used_underscore = true,
            "-q" | "--quiet" => args.quiet = true,
            "-e" | "--edit" => args.edit = true,
            "-h" | "--hidden" => args.hidden = true,
            "-f" | "--fail" => args.fail = true,
            "-V" | "--version" => args.version = true,
            "--help" => {
                print_help();
                process::exit(0);
            }
            "-o" | "--output-format" => {
                i += 1;
                if i < cli_args.len() {
                    args.output_format = match cli_args[i].as_str() {
                        "json" => OutputFormat::Json,
                        "human-readable" => OutputFormat::HumanReadable,
                        _ => OutputFormat::HumanReadable,
                    };
                }
            }
            "--exclude" => {
                i += 1;
                while i < cli_args.len() && !cli_args[i].starts_with('-') && cli_args[i] != "--" {
                    args.exclude.push(PathBuf::from(&cli_args[i]));
                    i += 1;
                }
                i -= 1;
            }
            s if s.starts_with('-') => {
                // Unknown flag
            }
            _ => {
                args.file_paths.push(PathBuf::from(arg));
            }
        }
        i += 1;
    }

    if args.file_paths.is_empty() {
        args.file_paths.push(PathBuf::from("."));
    }

    args
}

fn print_help() {
    println!("Find dead code in .nix files

Usage: executable [OPTIONS] [FILE_PATHS]...

Arguments:
  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]

Options:
  -l, --no-lambda-arg                  Don't check lambda parameter arguments
  -L, --no-lambda-pattern-names        Don't check lambda attrset pattern names (don't break nixpkgs callPackage)
  -_, --no-underscore                  Don't check any bindings that start with a _
                                       (Lambda arguments starting with _ are not checked anyway.)
  -W, --warn-used-underscore           Warn if bindings are referenced that start with '_'
  -q, --quiet                          Don't print dead code report
  -e, --edit                           Remove unused code and write to source file
  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files
      --help                           
  -f, --fail                           Exit with 1 if unused code has been found
  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]
      --exclude <EXCLUDES>...          Files to exclude from analysis
  -V, --version                        Print version");
}

#[derive(Debug, Clone)]
pub struct Issue {
    pub line: usize,
    pub column: usize,
    pub end_column: usize,
    pub message: String,
}

fn main() {
    let args = parse_args();

    if args.version {
        println!("deadnix 1.3.1");
        return;
    }

    let exclude_set: HashSet<PathBuf> = args.exclude.iter().cloned().collect();
    let mut all_issues = Vec::new();
    let mut has_issues = false;

    for file_path in &args.file_paths {
        let paths = collect_nix_files(file_path, args.hidden, &exclude_set);

        for path in paths {
            match analyze_file(&path, &args) {
                Ok((issues, has_dead_code)) => {
                    all_issues.push((path.clone(), issues));
                    if has_dead_code {
                        has_issues = true;
                    }
                }
                Err(e) => {
                    eprintln!("Error analyzing {}: {}", path.display(), e);
                }
            }
        }
    }

    if !args.quiet {
        match args.output_format {
            OutputFormat::HumanReadable => {
                output_human_readable(&all_issues);
            }
            OutputFormat::Json => {
                output_json(&all_issues);
            }
        }
    }

    if args.fail && has_issues {
        process::exit(1);
    }
}

fn collect_nix_files(
    path: &Path,
    hidden: bool,
    exclude: &HashSet<PathBuf>,
) -> Vec<PathBuf> {
    let mut files = Vec::new();

    if path.is_file() {
        if path.extension().map(|e| e == "nix").unwrap_or(false) {
            files.push(path.to_path_buf());
        }
    } else if path.is_dir() {
        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let path = entry.path();

                if exclude.contains(&path) {
                    continue;
                }

                if path.is_file() {
                    let file_name = path.file_name().map(|n| n.to_string_lossy());
                    if let Some(name) = file_name {
                        if name.ends_with(".nix") {
                            files.push(path);
                        }
                    }
                } else if path.is_dir() && hidden {
                    files.extend(collect_nix_files(&path, hidden, exclude));
                } else if path.is_dir() {
                    let dir_name = path.file_name().map(|n| n.to_string_lossy());
                    if let Some(name) = dir_name {
                        if !name.starts_with('.') {
                            files.extend(collect_nix_files(&path, hidden, exclude));
                        }
                    }
                }
            }
        }
    }

    files
}

fn analyze_file(path: &Path, args: &Args) -> Result<(Vec<Issue>, bool), String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Failed to read file: {}", e))?;

    let config = analyzer::AnalysisConfig {
        check_lambda_args: !args.no_lambda_arg,
        check_lambda_pattern_names: !args.no_lambda_pattern_names,
        check_underscore: !args.no_underscore,
        warn_used_underscore: args.warn_used_underscore,
    };

    let analyzer = NixAnalyzer::new(config);
    let issues = analyzer.analyze(&content)?;
    let has_issues = !issues.is_empty();

    Ok((issues, has_issues))
}

fn output_human_readable(all_issues: &[(PathBuf, Vec<Issue>)]) {
    let mut has_output = false;

    for (_, issues) in all_issues {
        if !issues.is_empty() {
            has_output = true;
            break;
        }
    }

    if !has_output {
        return;
    }

    eprintln!("\u{1b}[33mWarning:\u{1b}[0m Unused declarations were found.");

    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        for issue in issues {
            println!("{}: {} ({}:{})", 
                path.display(),
                issue.message,
                issue.line,
                issue.column
            );
        }
    }
}

fn output_json(all_issues: &[(PathBuf, Vec<Issue>)]) {
    for (path, issues) in all_issues {
        if issues.is_empty() {
            continue;
        }

        let mut results = String::from("[");
        for (i, issue) in issues.iter().enumerate() {
            if i > 0 {
                results.push(',');
            }
            results.push_str(&format!(
                r#"{{"line":{},"column":{},"endColumn":{},"message":"{}"}}"#,
                issue.line,
                issue.column,
                issue.end_column,
                escape_json_string(&issue.message)
            ));
        }
        results.push(']');

        let output = format!(
            r#"{{"file":"{}","results":{}}}"#,
            escape_json_string(&path.to_string_lossy()),
            results
        );

        println!("{}", output);
    }
}

fn escape_json_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}
