struct FileAnalyzer<'a> {
    content: &'a str,
    lines: Vec<&'a str>,
    config: &'a AnalysisConfig,
    issues: Vec<Issue>,
    definitions: HashMap<String, (usize, usize)>,
    usages: HashSet<String>,
}

impl<'a> FileAnalyzer<'a> {
    fn new(content: &'a str, config: &'a AnalysisConfig) -> Self {
        let lines: Vec<&str> = content.lines().collect();
        FileAnalyzer {
            content,
            lines,
            config,
            issues: Vec::new(),
            definitions: HashMap::new(),
            usages: HashSet::new(),
        }
    }

    fn analyze(&mut self) -> Result<Vec<Issue>, String> {
        // Parse the entire file
        self.parse_file();

        // Find unused definitions
        for (name, (line, col)) in &self.definitions {
            if !self.usages.contains(name) {
                self.issues.push(Issue {
                    line: *line,
                    column: *col,
                    end_column: col + name.len(),
                    message: format_message(&name),
                });
            }
        }

        self.issues.sort_by_key(|i| (i.line, i.column));
        Ok(self.issues.clone())
    }

    fn parse_file(&mut self) {
        let mut pos = 0;
        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);
            if pos >= self.content.len() {
                break;
            }

            pos = self.parse_toplevel(pos);
        }
    }

    fn skip_whitespace_and_comments(&self, mut pos: usize) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch.is_whitespace() {
                pos += 1;
            } else if ch == '#' && (pos + 1 >= self.content.len() || self.content.as_bytes()[pos + 1] as char != '{') {
                while pos < self.content.len() && self.content.as_bytes()[pos] as char != '\n' {
                    pos += 1;
                }
            } else {
                break;
            }
        }
        pos
    }

    fn parse_toplevel(&mut self, pos: usize) -> usize {
        // Check if this is a let binding at top level
        if self.content[pos..].starts_with("let") {
            self.parse_let_block(pos)
        } else if self.content[pos..].starts_with("rec") {
            pos + 3 // Skip rec
        } else if let Some(ch) = self.content.as_bytes().get(pos) {
            if (*ch as char).is_alphabetic() || *ch == b'_' {
                // This might be a lambda parameter
                self.parse_identifier_or_expression(pos)
            } else {
                pos + 1
            }
        } else {
            pos
        }
    }

    fn parse_let_block(&mut self, mut pos: usize) -> usize {
        pos += 3; // Skip "let"
        pos = self.skip_whitespace_and_comments(pos);

        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            if self.content[pos..].starts_with("in") {
                pos += 2;
                break;
