            // Parse a binding
            pos = self.parse_binding(pos);
        }

        pos = self.skip_whitespace_and_comments(pos);

        // Parse the body expression
        pos = self.parse_expression(pos);

        pos
    }

    fn parse_binding(&mut self, mut pos: usize) -> usize {
        pos = self.skip_whitespace_and_comments(pos);

        // Check for inherit
        if self.content[pos..].starts_with("inherit") {
            pos = self.parse_inherit_statement(pos);
        } else {
            // Regular binding: name = expr;
            let start_pos = pos;
            pos = self.skip_to_equals(pos);

            let name = self.extract_identifier(&self.content[start_pos..pos].trim());
            let line_no = self.get_line_number(start_pos);
            let col_no = self.get_column_number(start_pos);

            if !name.is_empty() && is_valid_identifier(&name) {
                if !name.starts_with('_') || self.config.check_underscore {
                    self.definitions.insert(name.clone(), (line_no, col_no));
                }
