            pos = self.skip_whitespace_and_comments(pos);
        }

        // Parse inherited names
        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            let ch = self.content.as_bytes()[pos] as char;
            if ch == ';' {
                pos += 1;
                break;
            }

            if ch.is_alphabetic() || ch == '_' {
                let ident_start = pos;
                while pos < self.content.len() {
                    let ch = self.content.as_bytes()[pos] as char;
                    if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                        pos += 1;
                    } else {
                        break;
                    }
                }

                let name = &self.content[ident_start..pos];
                if is_valid_identifier(name) {
                    let line_no = self.get_line_number(ident_start);
                    let col_no = self.get_column_number(ident_start);

                    if !name.starts_with('_') || self.config.check_underscore {
                        self.definitions.insert(name.to_string(), (line_no, col_no));
                    }
