                }
            } else {
                pos += 1;
            }
        }

        pos
    }

    fn parse_expression(&mut self, mut pos: usize) -> usize {
        loop {
            pos = self.skip_whitespace_and_comments(pos);

            if pos >= self.content.len() {
                break;
            }

            let ch = self.content.as_bytes()[pos] as char;

            match ch {
                // Handle lambdas
                'l' if self.content[pos..].starts_with("let") => {
                    pos = self.parse_let_block(pos);
                }
                'i' if self.content[pos..].starts_with("if") => {
                    pos += 2;
                    pos = self.parse_expression(pos); // condition
                    if self.content[pos..].starts_with("then") {
                        pos += 4;
                    }
                    pos = self.parse_expression(pos); // then expr
                    if self.content[pos..].starts_with("else") {
                        pos += 4;
                    }
                    pos = self.parse_expression(pos); // else expr
                }
                '{' => {
                    pos = self.parse_attrset(pos);
                }
                '[' => {
                    pos = self.parse_list(pos);
                }
                '"' => {
                    pos = self.parse_string(pos);
                }
                '(' => {
                    pos += 1;
                    pos = self.parse_expression(pos);
                    if pos < self.content.len() && self.content.as_bytes()[pos] as char == ')' {
                        pos += 1;
                    }
                }
                _ if ch.is_alphabetic() || ch == '_' => {
                    let ident_start = pos;
                    pos = self.extract_ident_pos(pos);
                    let ident = &self.content[ident_start..pos];

                    // Record usage
                    if is_valid_identifier(ident) {
                        if !ident.starts_with('_') || self.config.warn_used_underscore {
                            self.usages.insert(ident.to_string());
                        }
                    }

                    // Check for lambda
                    let next_pos = self.skip_whitespace_and_comments(pos);
                    if next_pos < self.content.len() && self.content.as_bytes()[next_pos] as char == ':' {
                        // This is a lambda parameter
                        if self.config.check_lambda_args && !ident.starts_with('_') {
                            let line_no = self.get_line_number(ident_start);
                            let col_no = self.get_column_number(ident_start);
                            self.definitions.insert(ident.to_string(), (line_no, col_no));
                        }
                        pos = next_pos + 1;
                        pos = self.parse_expression(pos);
                    }

                    // Check for attribute access
                    let next_pos = self.skip_whitespace_and_comments(pos);
                    if next_pos < self.content.len() && self.content.as_bytes()[next_pos] as char == '.' {
                        pos = next_pos + 1;
                        // Skip the attribute name
                        pos = self.skip_whitespace_and_comments(pos);
                        while pos < self.content.len() {
                            let ch = self.content.as_bytes()[pos] as char;
                            if ch.is_alphanumeric() || ch == '_' {
                                pos += 1;
                            } else {
                                break;
                            }
                        }
                    }

                    break;
                }
                ';' | '}' | ']' | ')' | ',' => {
                    break;
                }
                '@' => {
                    pos += 1;
                    pos = self.skip_whitespace_and_comments(pos);

                    // Parse @name or @{...}
                    if pos < self.content.len() && self.content.as_bytes()[pos] as char == '{' {
                        pos = self.parse_lambda_attrset(pos);
                    } else {
                        let name_start = pos;
                        while pos < self.content.len() {
                            let ch = self.content.as_bytes()[pos] as char;
                            if ch.is_alphanumeric() || ch == '_' {
                                pos += 1;
                            } else {
                                break;
                            }
                        }
                        let name = &self.content[name_start..pos];
                        if is_valid_identifier(name) && self.config.check_lambda_pattern_names && !name.starts_with('_') {
                            let line_no = self.get_line_number(name_start);
                            let col_no = self.get_column_number(name_start);
                            self.definitions.insert(name.to_string(), (line_no, col_no));
                        }
                    }

                    pos = self.skip_whitespace_and_comments(pos);
                    if pos < self.content.len() && self.content.as_bytes()[pos] as char == ':' {
                        pos += 1;
                        pos = self.parse_expression(pos);
                    }

                    break;
                }
                _ => {
                    pos += 1;
                }
            }

            // Check for operators that continue the expression
            let next_pos = self.skip_whitespace_and_comments(pos);
            if next_pos >= self.content.len() {
                break;
            }

            let next_ch = self.content.as_bytes()[next_pos] as char;
            if matches!(next_ch, '+' | '-' | '*' | '/' | '.' | ' ') {
                pos = next_pos;
                if next_ch != ' ' && next_ch != '.' {
                    pos += 1;
                }
            } else {
                break;
            }
        }

        pos
    }

    fn parse_lambda_attrset(&mut self, mut pos: usize) -> usize {
        if self.content.as_bytes()[pos] as char != '{' {
            return pos;
        }
        pos += 1;

        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            let ch = self.content.as_bytes()[pos] as char;
            if ch == '}' {
                pos += 1;
                break;
            }

            if ch == '.' && self.content[pos..].starts_with("...") {
                pos += 3;
            } else if ch.is_alphabetic() || ch == '_' {
                let name_start = pos;
                while pos < self.content.len() {
                    let ch = self.content.as_bytes()[pos] as char;
                    if ch.is_alphanumeric() || ch == '_' || ch == '-' {
                        pos += 1;
                    } else {
                        break;
                    }
                }

                let name = &self.content[name_start..pos];
                if is_valid_identifier(name) && self.config.check_lambda_pattern_names && !name.starts_with('_') {
                    let line_no = self.get_line_number(name_start);
                    let col_no = self.get_column_number(name_start);
                    self.definitions.insert(name.to_string(), (line_no, col_no));
                }

                // Handle default value
                pos = self.skip_whitespace_and_comments(pos);
                if pos < self.content.len() && self.content.as_bytes()[pos] as char == '?' {
                    pos += 1;
                    pos = self.skip_whitespace_and_comments(pos);
                    pos = self.parse_expression(pos);
                }

                pos = self.skip_whitespace_and_comments(pos);
                if pos < self.content.len() && self.content.as_bytes()[pos] as char == ',' {
                    pos += 1;
                }
            } else {
                pos += 1;
            }
        }

        pos
    }

    fn parse_attrset(&mut self, mut pos: usize) -> usize {
        pos += 1; // Skip '{'

        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            let ch = self.content.as_bytes()[pos] as char;
            if ch == '}' {
                pos += 1;
                break;
            } else if ch == 'r' && self.content[pos..].starts_with("rec") {
                pos += 3;
            } else if ch.is_alphabetic() || ch == '_' || ch == '"' || ch == '$' {
                // Skip key
                if ch == '"' || ch == '$' {
                    pos = self.parse_string(pos);
                } else {
                    while pos < self.content.len() {
                        let ch = self.content.as_bytes()[pos] as char;
                        if ch.is_alphanumeric() || ch == '_' {
                            pos += 1;
                        } else {
                            break;
                        }
                    }
                }

                pos = self.skip_whitespace_and_comments(pos);
                if pos < self.content.len() && self.content.as_bytes()[pos] as char == '=' {
                    pos += 1;
                    pos = self.parse_expression(pos);
                }

                pos = self.skip_whitespace_and_comments(pos);
                if pos < self.content.len() && self.content.as_bytes()[pos] as char == ';' {
                    pos += 1;
                }
            } else {
                pos += 1;
            }
        }

        pos
    }

    fn parse_list(&mut self, mut pos: usize) -> usize {
        pos += 1; // Skip '['

        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            let ch = self.content.as_bytes()[pos] as char;
            if ch == ']' {
                pos += 1;
                break;
            }

            pos = self.parse_expression(pos);
        }

        pos
    }

    fn parse_string(&self, mut pos: usize) -> usize {
        pos += 1; // Skip opening quote
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch == '"' {
                pos += 1;
                break;
            } else if ch == '\\' {
                pos += 2;
            } else if ch == '$' && pos + 1 < self.content.len() && self.content.as_bytes()[pos + 1] as char == '{' {
                // String interpolation - skip the ${ ... }
                pos += 2;
                let mut brace_count = 1;
                while pos < self.content.len() && brace_count > 0 {
                    let ch = self.content.as_bytes()[pos] as char;
                    if ch == '{' {
                        brace_count += 1;
                    } else if ch == '}' {
                        brace_count -= 1;
                    }
                    pos += 1;
                }
            } else {
                pos += 1;
            }
        }
        pos
    }

    fn parse_identifier_or_expression(&mut self, mut pos: usize) -> usize {
        let ident_start = pos;
        pos = self.extract_ident_pos(pos);
        let ident = &self.content[ident_start..pos];

        if is_valid_identifier(ident) {
            self.usages.insert(ident.to_string());
        }

        pos = self.skip_whitespace_and_comments(pos);

        // Check for @
        if pos < self.content.len() && self.content.as_bytes()[pos] as char == '@' {
            pos += 1;
            pos = self.skip_whitespace_and_comments(pos);

            if pos < self.content.len() && self.content.as_bytes()[pos] as char == '{' {
                pos = self.parse_lambda_attrset(pos);
            } else {
                while pos < self.content.len() {
                    let ch = self.content.as_bytes()[pos] as char;
                    if ch.is_alphanumeric() || ch == '_' {
                        pos += 1;
                    } else {
                        break;
                    }
                }
            }

            pos = self.skip_whitespace_and_comments(pos);
        }

        // Check for :
        if pos < self.content.len() && self.content.as_bytes()[pos] as char == ':' {
            pos += 1;
            pos = self.parse_expression(pos);
        }

        pos
    }

    fn skip_to_equals(&self, mut pos: usize) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch == '=' {
                break;
            }
            pos += 1;
        }
        pos
    }

    fn skip_to_char(&self, mut pos: usize, target: char) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch == target {
                break;
            }
            pos += 1;
        }
        pos
    }

    fn extract_ident_pos(&self, mut pos: usize) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                pos += 1;
            } else {
                break;
            }
        }
        pos
    }

    fn extract_identifier(&self, s: &str) -> String {
        let mut result = String::new();
        for ch in s.chars() {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
            } else {
                break;
            }
        }
        result
    }

    fn get_line_number(&self, pos: usize) -> usize {
        let mut line = 1;
        for i in 0..pos.min(self.content.len()) {
            if self.content.as_bytes()[i] as char == '\n' {
                line += 1;
            }
        }
        line
    }

    fn get_column_number(&self, pos: usize) -> usize {
        let mut col = 1;
        for i in (0..pos).rev() {
            if self.content.as_bytes()[i] as char == '\n' {
                break;
            }
            col += 1;
        }
        col
    }
}

fn is_valid_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '\'' )
}

fn format_message(name: &str) -> String {
    // Determine the type of binding based on context
    // For now, just use "let binding"
    format!("Unused let binding: {}", name)
}
