                        pos += 1;
                    } else {
                        break;
                    }
                }
            }

            pos = self.skip_whitespace_and_comments(pos);
        }

        // Check for :
        if pos < self.content.len() && self.content.as_bytes()[pos] as char == ':' {
            pos += 1;
            pos = self.parse_expression(pos);
        }

        pos
    }

    fn skip_to_equals(&self, mut pos: usize) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch == '=' {
                break;
            }
            pos += 1;
        }
        pos
    }

    fn skip_to_char(&self, mut pos: usize, target: char) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch == target {
                break;
            }
            pos += 1;
        }
        pos
    }

    fn extract_ident_pos(&self, mut pos: usize) -> usize {
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                pos += 1;
            } else {
                break;
            }
        }
        pos
    }

    fn extract_identifier(&self, s: &str) -> String {
        let mut result = String::new();
        for ch in s.chars() {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
            } else {
                break;
            }
        }
        result
    }

    fn get_line_number(&self, pos: usize) -> usize {
        let mut line = 1;
        for i in 0..pos.min(self.content.len()) {
            if self.content.as_bytes()[i] as char == '\n' {
                line += 1;
            }
        }
        line
    }

    fn get_column_number(&self, pos: usize) -> usize {
        let mut col = 1;
        for i in (0..pos).rev() {
            if self.content.as_bytes()[i] as char == '\n' {
                break;
            }
            col += 1;
        }
        col
    }
}

fn is_valid_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '\'' )
}

fn format_message(name: &str) -> String {
    // Determine the type of binding based on context
    // For now, just use "let binding"
    format!("Unused let binding: {}", name)
}
