    }

    fn parse_attrset(&mut self, mut pos: usize) -> usize {
        pos += 1; // Skip '{'

        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            let ch = self.content.as_bytes()[pos] as char;
            if ch == '}' {
                pos += 1;
                break;
            } else if ch == 'r' && self.content[pos..].starts_with("rec") {
                pos += 3;
            } else if ch.is_alphabetic() || ch == '_' || ch == '"' || ch == '$' {
                // Skip key
                if ch == '"' || ch == '$' {
                    pos = self.parse_string(pos);
                } else {
                    while pos < self.content.len() {
                        let ch = self.content.as_bytes()[pos] as char;
                        if ch.is_alphanumeric() || ch == '_' {
                            pos += 1;
                        } else {
                            break;
                        }
                    }
