                pos = self.skip_whitespace_and_comments(pos);
                if pos < self.content.len() && self.content.as_bytes()[pos] as char == '=' {
                    pos += 1;
                    pos = self.parse_expression(pos);
                }

                pos = self.skip_whitespace_and_comments(pos);
                if pos < self.content.len() && self.content.as_bytes()[pos] as char == ';' {
                    pos += 1;
                }
            } else {
                pos += 1;
            }
        }

        pos
    }

    fn parse_list(&mut self, mut pos: usize) -> usize {
        pos += 1; // Skip '['

        while pos < self.content.len() {
            pos = self.skip_whitespace_and_comments(pos);

            let ch = self.content.as_bytes()[pos] as char;
            if ch == ']' {
                pos += 1;
                break;
            }

            pos = self.parse_expression(pos);
        }

        pos
    }

    fn parse_string(&self, mut pos: usize) -> usize {
        pos += 1; // Skip opening quote
        while pos < self.content.len() {
            let ch = self.content.as_bytes()[pos] as char;
            if ch == '"' {
                pos += 1;
                break;
            } else if ch == '\\' {
                pos += 2;
            } else if ch == '$' && pos + 1 < self.content.len() && self.content.as_bytes()[pos + 1] as char == '{' {
                // String interpolation - skip the ${ ... }
                pos += 2;
