            lines,
            config,
            issues: Vec::new(),
            definitions: HashMap::new(),
            usages: HashSet::new(),
        }
    }

    fn analyze(&mut self) -> Result<Vec<Issue>, String> {
        // Parse the entire file
        self.parse_file();

        // Find unused definitions
        for (name, (line, col)) in &self.definitions {
            if !self.usages.contains(name) {
                self.issues.push(Issue {
                    line: *line,
                    column: *col,
                    end_column: col + name.len(),
                    message: format_message(&name),
