use crate::Issue;
use std::collections::{HashMap, HashSet};

#[derive(Clone)]
pub struct AnalysisConfig {
    pub check_lambda_args: bool,
    pub check_lambda_pattern_names: bool,
    pub check_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct NixAnalyzer {
    config: AnalysisConfig,
}

#[derive(Clone, Debug)]
struct Binding {
    name: String,
    line: usize,
    column: usize,
    message_type: String, // "Unused let binding", "Unused lambda argument", etc
}

impl NixAnalyzer {
    pub fn new(config: AnalysisConfig) -> Self {
        NixAnalyzer { config }
    }

    pub fn analyze(&self, content: &str) -> Result<Vec<Issue>, String> {
        let mut analyzer = ContentAnalyzer::new(content, &self.config);
        analyzer.analyze()
    }
}

struct ContentAnalyzer<'a> {
    content: &'a str,
    config: &'a AnalysisConfig,
}

impl<'a> ContentAnalyzer<'a> {
    fn new(content: &'a str, config: &'a AnalysisConfig) -> Self {
        ContentAnalyzer { content, config }
    }

    fn analyze(&mut self) -> Result<Vec<Issue>, String> {
        let mut collector = DeadCodeCollector::new(self.config);
        collector.analyze_expr(self.content, 0);
        Ok(collector.issues)
    }
}

struct DeadCodeCollector<'a> {
    config: &'a AnalysisConfig,
    issues: Vec<Issue>,
    bindings_stack: Vec<HashMap<String, Binding>>,
    usages: HashSet<String>,
}

impl<'a> DeadCodeCollector<'a> {
    fn new(config: &'a AnalysisConfig) -> Self {
        DeadCodeCollector {
            config,
            issues: Vec::new(),
            bindings_stack: vec![HashMap::new()],
            usages: HashSet::new(),
        }
    }

    fn analyze_expr(&mut self, content: &str, _pos: usize) {
        // First pass: collect all identifiers and their usages
        self.collect_identifiers(content);

        // Find definitions and check for unused
        self.find_unused_bindings(content);
    }

    fn collect_identifiers(&mut self, content: &str) {
        let mut chars = content.chars().peekable();
        let mut current_word = String::new();

        while let Some(ch) = chars.next() {
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                current_word.push(ch);
            } else {
                if !current_word.is_empty() && is_identifier(&current_word) {
                    // Check if this looks like a keyword first
                    if !matches!(current_word.as_str(), "let" | "in" | "if" | "then" | "else" | "inherit" | "rec" | "with" | "assert" | "rec") {
                        if !current_word.starts_with('_') || self.config.warn_used_underscore {
                            self.usages.insert(current_word.clone());
                        }
                    }
                }
                current_word.clear();
            }
        }
    }

    fn find_unused_bindings(&mut self, content: &str) {
        let lines: Vec<&str> = content.lines().collect();
        let mut i = 0;

        while i < lines.len() {
            let line = lines[i];
            let line_num = i + 1;

            // Skip empty and comment lines
            let trimmed = line.trim();
            if trimmed.is_empty() || trimmed.starts_with('#') {
                i += 1;
                continue;
            }

            // Check for lambda parameters at line start
            if line.contains('@') && line.contains('{') {
                self.extract_lambda_params(line, line_num);
            }

            // Check for let bindings
            if line.contains(" = ") && !trimmed.starts_with("inherit") {
                self.extract_let_binding(line, line_num);
            }

            // Check for inherit statements
            if trimmed.starts_with("inherit") {
                self.extract_inherit_bindings(line, line_num);
            }

            i += 1;
        }
    }

    fn extract_lambda_params(&mut self, line: &str, line_num: usize) {
        // Pattern: { arg1, arg2, ... }@name:
        if let Some(brace_start) = line.find('{') {
            if let Some(brace_end) = line.find('}') {
                if let Some(at_pos) = line.find('@') {
                    if brace_start < brace_end && brace_end < at_pos {
                        let params_str = &line[brace_start + 1..brace_end];

                        // Extract individual parameters
                        for param in params_str.split(',') {
                            let param_trimmed = param.trim();
                            if param_trimmed == "..." {
                                continue;
                            }

                            // Get name before ? if present
                            let name = param_trimmed.split('?').next().unwrap_or("").trim();

                            if !name.is_empty() && is_identifier(name) {
                                if self.config.check_lambda_pattern_names {
                                    if !name.starts_with('_') || self.config.check_underscore {
                                        let col = line.find(name).unwrap_or(0) + 1;
                                        if !self.usages.contains(name) {
                                            self.issues.push(Issue {
                                                line: line_num,
                                                column: col,
                                                end_column: col + name.len(),
                                                message: "Unused lambda pattern: ".to_string() + name,
                                            });
                                        }
                                    }
                                }
                            }
                        }

                        // Extract name after @
                        let after_at = &line[at_pos + 1..];
                        let name_after_at = after_at.trim().split(':').next().unwrap_or("").trim();
                        if !name_after_at.is_empty() && is_identifier(name_after_at) && name_after_at != "{" {
                            if self.config.check_lambda_pattern_names {
                                if !name_after_at.starts_with('_') || self.config.check_underscore {
                                    let col = line.find(name_after_at).unwrap_or(0) + 1;
                                    if !self.usages.contains(name_after_at) {
                                        self.issues.push(Issue {
                                            line: line_num,
                                            column: col,
                                            end_column: col + name_after_at.len(),
                                            message: "Unused lambda pattern: ".to_string() + name_after_at,
                                        });
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Also handle simple lambdas like: unused: false
        if line.contains(": ") && line.contains('{') == false {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len() >= 2 {
                let before_colon = parts[0].trim();
                if is_identifier(before_colon) && self.config.check_lambda_args {
                    if !before_colon.starts_with('_') || self.config.check_underscore {
                        let col = line.find(before_colon).unwrap_or(0) + 1;
                        if !self.usages.contains(before_colon) {
                            self.issues.push(Issue {
                                line: line_num,
                                column: col,
                                end_column: col + before_colon.len(),
                                message: "Unused lambda argument: ".to_string() + before_colon,
                            });
                        }
                    }
                }
            }
        }
    }

    fn extract_let_binding(&mut self, line: &str, line_num: usize) {
        if let Some(eq_pos) = line.find(" = ") {
            let before_eq = &line[..eq_pos].trim_end();
            let name = before_eq.trim();

            if is_identifier(name) && !name.contains('{') && !name.contains('[') {
                if !name.starts_with('_') || self.config.check_underscore {
                    let col = line.find(name).unwrap_or(0) + 1;
                    if !self.usages.contains(name) {
                        self.issues.push(Issue {
                            line: line_num,
                            column: col,
                            end_column: col + name.len(),
                            message: "Unused let binding: ".to_string() + name,
                        });
                    }
                }
            }
        }
    }

    fn extract_inherit_bindings(&mut self, line: &str, line_num: usize) {
        // inherit (source) name1 name2;
        // or
        // inherit name1 name2;

        if let Some(paren_start) = line.find('(') {
            if let Some(paren_end) = line.find(')') {
                let after_paren = &line[paren_end + 1..];
                let inherit_names = after_paren.split_whitespace()
                    .filter(|s| !s.is_empty() && *s != ";");

                for name in inherit_names {
                    let clean_name = name.trim_end_matches(';');
                    if is_identifier(clean_name) {
                        if !clean_name.starts_with('_') || self.config.check_underscore {
                            let col = line.find(clean_name).unwrap_or(0) + 1;
                            if !self.usages.contains(clean_name) {
                                self.issues.push(Issue {
                                    line: line_num,
                                    column: col,
                                    end_column: col + clean_name.len(),
                                    message: "Unused let binding: ".to_string() + clean_name,
                                });
                            }
                        }
                    }
                }
            }
        } else {
            // Simple inherit without parentheses
            let after_inherit = line.trim_start_matches("inherit").trim();
            let names = after_inherit.split_whitespace()
                .filter(|s| !s.is_empty() && *s != ";");

            for name in names {
                let clean_name = name.trim_end_matches(';');
                if is_identifier(clean_name) {
                    if !clean_name.starts_with('_') || self.config.check_underscore {
                        let col = line.find(clean_name).unwrap_or(0) + 1;
                        if !self.usages.contains(clean_name) {
                            self.issues.push(Issue {
                                line: line_num,
                                column: col,
                                end_column: col + clean_name.len(),
                                message: "Unused let binding: ".to_string() + clean_name,
                            });
                        }
                    }
                }
            }
        }
    }
}

fn is_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-' || c == '\'' )
}
