use crate::Issue;
use std::collections::{HashMap, HashSet};

#[derive(Clone)]
pub struct AnalysisConfig {
    pub check_lambda_args: bool,
    pub check_lambda_pattern_names: bool,
    pub check_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct NixAnalyzer {
    config: AnalysisConfig,
}

impl NixAnalyzer {
    pub fn new(config: AnalysisConfig) -> Self {
        NixAnalyzer { config }
    }

    pub fn analyze(&self, content: &str) -> Result<Vec<Issue>, String> {
        let mut issues = Vec::new();
        let mut parser = Parser::new(content, &self.config);
        parser.parse(&mut issues);

        // Sort by line and column
        issues.sort_by_key(|i| (i.line, i.column));
        Ok(issues)
    }
}

struct Parser<'a> {
    content: &'a str,
    config: &'a AnalysisConfig,
    bytes: Vec<u8>,
    pos: usize,
    line: usize,
    column: usize,
}

impl<'a> Parser<'a> {
    fn new(content: &'a str, config: &'a AnalysisConfig) -> Self {
        let bytes = content.as_bytes().to_vec();
        Parser {
            content,
            config,
            bytes,
            pos: 0,
            line: 1,
            column: 1,
        }
    }

    fn parse(&mut self, issues: &mut Vec<Issue>) {
        let mut definitions: HashMap<String, (usize, usize, String)> = HashMap::new();
        let mut usages: HashSet<String> = HashSet::new();

        // First, collect all identifiers that look like usages
        self.collect_usages(&mut usages);

        // Reset position
        self.pos = 0;
        self.line = 1;
        self.column = 1;

        // Second, collect definitions
        self.collect_definitions(&mut definitions);

        // Find unused definitions
        for (name, (line, col, msg_type)) in definitions {
            if !usages.contains(&name) {
                let end_col = col + name.len();
                let message = match msg_type.as_str() {
                    "lambda_pattern" => format!("Unused lambda pattern: {}", name),
                    "lambda_arg" => format!("Unused lambda argument: {}", name),
                    "inherit" => format!("Unused let binding: {}", name),
                    _ => format!("Unused let binding: {}", name),
                };
                issues.push(Issue {
                    line,
                    column: col,
                    end_column: end_col,
                    message,
                });
            }
        }
    }

    fn collect_usages(&mut self, usages: &mut HashSet<String>) {
        while self.pos < self.bytes.len() {
            self.skip_whitespace_and_comments();
            if self.pos >= self.bytes.len() {
                break;
            }

            let ch = self.bytes[self.pos] as char;
            if ch.is_alphabetic() || ch == '_' {
                let start = self.pos;
                let ident = self.read_identifier();
                if is_valid_identifier(&ident) && !is_keyword(&ident) {
                    usages.insert(ident);
                }
                self.pos = start + 1;
            } else {
                self.advance();
            }
        }
    }

    fn collect_definitions(&mut self, definitions: &mut HashMap<String, (usize, usize, String)>) {
        while self.pos < self.bytes.len() {
            self.skip_whitespace_and_comments();
            if self.pos >= self.bytes.len() {
                break;
            }

            let ch = self.bytes[self.pos] as char;

            // Check for top-level lambda (identifier@{ or identifier:)
            if ch.is_alphabetic() || ch == '_' {
                self.parse_top_level_lambda(definitions);
            }

            // Check for let bindings
            if self.match_keyword("let") {
                self.parse_let_bindings(definitions);
            }

            // Check for inherit
            if self.match_keyword("inherit") {
                self.parse_inherit(definitions);
            }

            self.advance();
        }
    }

    fn parse_top_level_lambda(&mut self, definitions: &mut HashMap<String, (usize, usize, String)>) {
        let line = self.line;
        let col = self.column;
        let start_pos = self.pos;

        let ident = self.read_identifier();
        if !is_valid_identifier(&ident) || is_keyword(&ident) {
            return;
        }

        self.skip_whitespace();

        // Check for @
        if self.pos < self.bytes.len() && self.bytes[self.pos] as char == '@' {
            if self.config.check_lambda_pattern_names && !ident.starts_with('_') {
