        if self.bytes[self.pos] as char != '{' {
            return;
        }
        self.advance(); // Skip {

        loop {
            self.skip_whitespace();
            if self.pos >= self.bytes.len() {
                break;
            }

            let ch = self.bytes[self.pos] as char;
            if ch == '}' {
                self.advance();
                break;
            }

            if ch == '.' {
                if self.match_token("...") {
                    self.pos += 3;
                } else {
                    self.advance();
                }
            } else if ch.is_alphabetic() || ch == '_' {
