                if self.pos < self.bytes.len() && self.bytes[self.pos] as char == '?' {
                    self.advance();
                    self.skip_whitespace();
                    self.skip_expression();
                }

                self.skip_whitespace();
                if self.pos < self.bytes.len() && self.bytes[self.pos] as char == ',' {
                    self.advance();
                }
            } else {
                self.advance();
            }
        }
    }

    fn parse_let_bindings(&mut self, definitions: &mut HashMap<String, (usize, usize, String)>) {
        if !self.match_keyword("let") {
            return;
        }
        self.pos += 3;
        self.skip_whitespace();

        while self.pos < self.bytes.len() {
            self.skip_whitespace();
            if self.match_keyword("in") {
                break;
            }

            // Parse binding
            if self.match_keyword("inherit") {
                self.parse_inherit(definitions);
            } else {
                let line = self.line;
                let col = self.column;
                let name = self.read_identifier();

                if is_valid_identifier(&name) {
                    self.skip_whitespace();
                    if self.pos < self.bytes.len() && self.bytes[self.pos] as char == '=' {
                        if !name.starts_with('_') || self.config.check_underscore {
