                ']' => bracket_depth -= 1,
                '(' => paren_depth += 1,
                ')' => paren_depth -= 1,
                ';' if brace_depth == 0 && bracket_depth == 0 && paren_depth == 0 => return,
                _ => {}
            }

            // Handle lambdas
            if (ch.is_alphabetic() || ch == '_') && paren_depth == 0 && brace_depth == 0 && bracket_depth == 0 {
                let ident = self.peek_identifier();
                if is_keyword(&ident) && ident == "let" {
                    // Nested let - skip it
                    self.skip_expression();
                    continue;
