    fn read_identifier(&mut self) -> String {
        let mut result = String::new();
        while self.pos < self.bytes.len() {
            let ch = self.bytes[self.pos] as char;
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
                self.advance();
            } else {
                break;
            }
        }
        result
    }

    fn peek_identifier(&self) -> String {
        let mut result = String::new();
        let mut pos = self.pos;
        while pos < self.bytes.len() {
            let ch = self.bytes[pos] as char;
            if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
                result.push(ch);
                pos += 1;
            } else {
                break;
            }
        }
        result
    }

    fn match_keyword(&self, kw: &str) -> bool {
        if self.pos + kw.len() > self.bytes.len() {
            return false;
        }

        for (i, ch) in kw.chars().enumerate() {
            if self.bytes[self.pos + i] as char != ch {
                return false;
            }
        }

        // Make sure it's not part of a larger identifier
        if self.pos + kw.len() < self.bytes.len() {
            let next_ch = self.bytes[self.pos + kw.len()] as char;
            if next_ch.is_alphanumeric() || next_ch == '_' {
                return false;
            }
        }

        true
    }

    fn match_token(&self, token: &str) -> bool {
        if self.pos + token.len() > self.bytes.len() {
            return false;
        }

        for (i, ch) in token.chars().enumerate() {
            if self.bytes[self.pos + i] as char != ch {
                return false;
            }
        }

        true
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.bytes.len() {
            let ch = self.bytes[self.pos] as char;
            if ch.is_whitespace() {
                self.advance();
            } else {
                break;
            }
        }
    }

    fn skip_whitespace_and_comments(&mut self) {
        loop {
            self.skip_whitespace();
            if self.pos < self.bytes.len() && self.bytes[self.pos] as char == '#' {
                while self.pos < self.bytes.len() && self.bytes[self.pos] as char != '\n' {
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn advance(&mut self) {
        if self.pos < self.bytes.len() {
            if self.bytes[self.pos] as char == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
            self.pos += 1;
        }
    }
}

fn is_valid_identifier(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
