use crate::Issue;
use std::collections::HashSet;

#[derive(Clone)]
pub struct AnalysisConfig {
    pub check_lambda_args: bool,
    pub check_lambda_pattern_names: bool,
    pub check_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct NixAnalyzer {
    config: AnalysisConfig,
}

impl NixAnalyzer {
    pub fn new(config: AnalysisConfig) -> Self {
        NixAnalyzer { config }
    }

    pub fn analyze(&self, content: &str) -> Result<Vec<Issue>, String> {
        let mut issues = Vec::new();
        let lines: Vec<&str> = content.lines().collect();

        // Collect all identifiers that appear to be used
        let mut usages = HashSet::new();
        for line in &lines {
            extract_identifiers_from_line(line, &mut usages);
        }

        // Collect all definitions
        for (line_idx, line) in lines.iter().enumerate() {
            let line_num = line_idx + 1;

            // Check for lambda parameters at line start: identifier@{...}:
            if line.contains('@') && line.contains('{') {
                extract_lambda_params(line, line_num, &self.config, &usages, &mut issues);
            }

            // Check for let bindings: name = expr;
            if line.contains(" = ") && !line.trim().starts_with("inherit") {
                extract_let_binding(line, line_num, &self.config, &usages, &mut issues);
            }

            // Check for inherit statements
            if line.trim().starts_with("inherit") {
                extract_inherit_bindings(line, line_num, &self.config, &usages, &mut issues);
            }
        }

        // Sort issues by line and column
        issues.sort_by_key(|i| (i.line, i.column));
        Ok(issues)
    }
}

fn extract_identifiers_from_line(line: &str, usages: &mut HashSet<String>) {
    let mut current_word = String::new();

    for ch in line.chars() {
        if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
            current_word.push(ch);
        } else {
            if !current_word.is_empty() && is_valid_ident(&current_word) {
                usages.insert(current_word.clone());
            }
            current_word.clear();
        }
    }

    if !current_word.is_empty() && is_valid_ident(&current_word) {
        usages.insert(current_word);
    }
}

fn extract_lambda_params(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    usages: &HashSet<String>,
    issues: &mut Vec<Issue>,
) {
    // Format: unusedArgs@{ unusedArg, usedArg, ... }:
    // or: { unusedArg, usedArg, ... }@name:

    if let Some(at_pos) = line.find('@') {
        if let Some(brace_start) = line.rfind('{') {
            if brace_start < at_pos {
                if let Some(brace_end) = line.find_all('{', '}') {
                    if brace_end > brace_start && brace_end < at_pos {
                        let params_str = &line[brace_start + 1..brace_end];

                        // Extract parameters
                        for param in params_str.split(',') {
                            let param_trim = param.trim();
                            if param_trim == "..." {
                                continue;
                            }

                            // Handle default values
                            let name = param_trim.split('?').next().unwrap_or("").trim();
                            if !name.is_empty() && is_valid_ident(name) {
                                if config.check_lambda_pattern_names && !name.starts_with('_') {
                                    if !usages.contains(name) {
                                        let col = find_position_in_line(line, name);
                                        issues.push(Issue {
                                            line: line_num,
                                            column: col,
                                            end_column: col + name.len(),
                                            message: format!("Unused lambda pattern: {}", name),
                                        });
                                    }
                                }
                            }
                        }

                        // Extract name before @
                        let before_at = &line[..at_pos].trim_end();
                        if before_at.ends_with('}') {
                            // The name is after @
                            let after_at = &line[at_pos + 1..].trim_start();
                            let name_after = after_at.split(':').next().unwrap_or("").trim();
                            if !name_after.is_empty() && name_after != "{" && is_valid_ident(name_after) {
                                if config.check_lambda_pattern_names && !name_after.starts_with('_') {
                                    if !usages.contains(name_after) {
                                        let col = find_position_in_line(line, name_after);
                                        issues.push(Issue {
                                            line: line_num,
                                            column: col,
                                            end_column: col + name_after.len(),
                                            message: format!("Unused lambda pattern: {}", name_after),
                                        });
                                    }
                                }
                            }
                        } else {
                            // The name is before @
                            let name_before = before_at.trim();
                            if is_valid_ident(name_before) {
                                if config.check_lambda_pattern_names && !name_before.starts_with('_') {
                                    if !usages.contains(name_before) {
                                        let col = find_position_in_line(line, name_before);
                                        issues.push(Issue {
                                            line: line_num,
                                            column: col,
                                            end_column: col + name_before.len(),
                                            message: format!("Unused lambda pattern: {}", name_before),
                                        });
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Handle lambda argument: name: expression
    if !line.contains('{') && line.contains(':') {
        if let Some(colon_pos) = line.find(':') {
            let before_colon = &line[..colon_pos].trim_end();
            if is_valid_ident(before_colon) && !before_colon.contains('=') {
                if config.check_lambda_args && !before_colon.starts_with('_') {
                    if !usages.contains(before_colon) {
                        let col = find_position_in_line(line, before_colon);
                        issues.push(Issue {
                            line: line_num,
                            column: col,
                            end_column: col + before_colon.len(),
                            message: format!("Unused lambda argument: {}", before_colon),
                        });
                    }
                }
            }
        }
    }
}

fn extract_let_binding(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    usages: &HashSet<String>,
    issues: &mut Vec<Issue>,
) {
    if let Some(eq_pos) = line.find(" = ") {
        let before_eq = &line[..eq_pos].trim_end();
        let name = before_eq.trim();

        if is_valid_ident(name) && !name.contains('{') && !name.contains('[') {
            if !name.starts_with('_') || config.check_underscore {
                if !usages.contains(name) {
                    let col = find_position_in_line(line, name);
                    issues.push(Issue {
                        line: line_num,
                        column: col,
                        end_column: col + name.len(),
                        message: format!("Unused let binding: {}", name),
                    });
                }
            }
        }
    }
}

fn extract_inherit_bindings(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    usages: &HashSet<String>,
    issues: &mut Vec<Issue>,
) {
    if let Some(paren_start) = line.find('(') {
        if let Some(paren_end) = line.find(')') {
            let after_paren = &line[paren_end + 1..];
            for name in after_paren.split_whitespace() {
                let clean_name = name.trim_end_matches(';');
                if is_valid_ident(clean_name) {
                    if !clean_name.starts_with('_') || config.check_underscore {
                        if !usages.contains(clean_name) {
                            let col = find_position_in_line(line, clean_name);
                            issues.push(Issue {
                                line: line_num,
                                column: col,
                                end_column: col + clean_name.len(),
                                message: format!("Unused let binding: {}", clean_name),
                            });
                        }
                    }
                }
            }
        }
    }
}

fn is_valid_ident(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    !matches!(s, "let" | "in" | "if" | "then" | "else" | "inherit" | "rec" | "with" | "assert" | "or" | "and" | "not" | "rec")
}

fn find_position_in_line(line: &str, needle: &str) -> usize {
    if let Some(pos) = line.find(needle) {
        pos + 1
    } else {
        1
    }
}

trait StrExt {
    fn find_all(&self, open: char, close: char) -> Option<usize>;
}

impl StrExt for str {
    fn find_all(&self, open: char, close: char) -> Option<usize> {
        let mut count = 0;
        for (i, ch) in self.chars().enumerate() {
            if ch == open {
                count += 1;
            } else if ch == close {
                count -= 1;
                if count == 0 {
                    return Some(i);
                }
            }
        }
        None
    }
}
