                let params_str = &line[brace_start + 1..actual_brace_end];

                // Extract parameters
                for param in params_str.split(',') {
                    let param_trim = param.trim();
                    if param_trim == "..." {
                        continue;
                    }

                    // Handle default values
                    let name = param_trim.split('?').next().unwrap_or("").trim();
                    if !name.is_empty() && is_valid_ident(name) {
                        if config.check_lambda_pattern_names && !name.starts_with('_') {
                            if !usages.contains(&name.to_string()) {
                                let col = find_position_in_line(line, name);
                                issues.push(Issue {
                                    line: line_num,
                                    column: col,
                                    end_column: col + name.len(),
                                    message: format!("Unused lambda pattern: {}", name),
                                });
                            }
                        }
                    }
                }

                // Extract name before @
                if at_pos > 0 {
                    let before_at = &line[..at_pos].trim_end();
                    let name_before = if before_at.ends_with('}') {
                        ""
                    } else {
                        before_at.trim()
                    };

                    if !name_before.is_empty() && is_valid_ident(name_before) {
                        if config.check_lambda_pattern_names && !name_before.starts_with('_') {
                            if !usages.contains(&name_before.to_string()) {
                                let col = find_position_in_line(line, name_before);
                                issues.push(Issue {
                                    line: line_num,
                                    column: col,
                                    end_column: col + name_before.len(),
                                    message: format!("Unused lambda pattern: {}", name_before),
                                });
                            }
                        }
                    }
                }

                // Extract name after @
                let after_at = &line[at_pos + 1..].trim_start();
                let name_after = after_at.split(':').next().unwrap_or("").split('{').next().unwrap_or("").trim();
                if !name_after.is_empty() && name_after != "{" && is_valid_ident(name_after) {
                    if config.check_lambda_pattern_names && !name_after.starts_with('_') {
                        if !usages.contains(&name_after.to_string()) {
