fn extract_lambda_argument(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    usages: &HashSet<String>,
    issues: &mut Vec<Issue>,
) {
    // Find the first identifier followed by :
    let mut current_word = String::new();
    let mut current_word_start = 0;
    let mut in_word = false;

    for (i, ch) in line.chars().enumerate() {
        if ch.is_alphabetic() || ch == '_' {
            if !in_word {
                current_word_start = i;
                in_word = true;
            }
            current_word.push(ch);
        } else if ch.is_alphanumeric() || ch == '-' || ch == '\'' {
            if in_word {
                current_word.push(ch);
            }
        } else if ch == ':' && in_word {
            // Found a lambda parameter
            if is_valid_ident(&current_word) && config.check_lambda_args && !current_word.starts_with('_') {
                if !usages.contains(&current_word) {
                    let col = current_word_start + 1;
                    issues.push(Issue {
                        line: line_num,
                        column: col,
                        end_column: col + current_word.len(),
                        message: format!("Unused lambda argument: {}", current_word),
                    });
                }
            }
            in_word = false;
            current_word.clear();
            break;
        } else {
            in_word = false;
            current_word.clear();
        }
    }
}

fn extract_let_binding(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    usages: &HashSet<String>,
