                        column: col,
                        end_column: col + name.len(),
                        message: format!("Unused let binding: {}", name),
                    });
                }
            }
        }
    }
}

fn extract_inherit_bindings(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    usages: &HashSet<String>,
    issues: &mut Vec<Issue>,
) {
    if let Some(_paren_start) = line.find('(') {
        if let Some(paren_end) = line.find(')') {
            let after_paren = &line[paren_end + 1..];
            for name in after_paren.split_whitespace() {
                let clean_name = name.trim_end_matches(';');
                if is_valid_ident(clean_name) {
                    if !clean_name.starts_with('_') || config.check_underscore {
                        if !usages.contains(&clean_name.to_string()) {
                            let col = find_position_in_line(line, clean_name);
                            issues.push(Issue {
                                line: line_num,
                                column: col,
                                end_column: col + clean_name.len(),
                                message: format!("Unused let binding: {}", clean_name),
                            });
                        }
                    }
                }
            }
        }
    }
}

fn is_valid_ident(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    !matches!(s, "let" | "in" | "if" | "then" | "else" | "inherit" | "rec" | "with" | "assert" | "or" | "and" | "not")
}

