use crate::Issue;
use std::collections::HashSet;

#[derive(Clone)]
pub struct AnalysisConfig {
    pub check_lambda_args: bool,
    pub check_lambda_pattern_names: bool,
    pub check_underscore: bool,
    pub warn_used_underscore: bool,
}

pub struct NixAnalyzer {
    config: AnalysisConfig,
}

impl NixAnalyzer {
    pub fn new(config: AnalysisConfig) -> Self {
        NixAnalyzer { config }
    }

    pub fn analyze(&self, content: &str) -> Result<Vec<Issue>, String> {
        let mut issues = Vec::new();
        let lines: Vec<&str> = content.lines().collect();

        let mut all_definitions = Vec::new();
        let mut all_usages = HashSet::new();

        // First pass: collect definitions and collect usages from "usage positions"
        for (line_idx, line) in lines.iter().enumerate() {
            let line_num = line_idx + 1;
            let trimmed = line.trim();

            if trimmed.starts_with('#') {
                continue;
            }

            // Collect definitions from this line
            collect_definitions_from_line(line, line_num, &self.config, &mut all_definitions);

            // Collect usages: right side of =, expressions after :, etc.
            collect_usages_from_line_smart(line, &mut all_usages);
        }

        // Third pass: report unused definitions
        for (name, line, col, msg_type) in all_definitions {
            if !all_usages.contains(&name) {
                let message = format!("Unused {}: {}", msg_type, name);
                issues.push(Issue {
                    line,
                    column: col,
                    end_column: col + name.len(),
                    message,
                });
            }
        }

        // Sort issues by line and column
        issues.sort_by_key(|i| (i.line, i.column));
        Ok(issues)
    }
}

fn collect_definitions_from_line(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    definitions: &mut Vec<(String, usize, usize, String)>,
) {
    let trimmed = line.trim();
    if trimmed.starts_with('#') {
        return;
    }

    // Pattern 1: Lambda argument at start: identifier:
    if !line.contains('{') && !line.contains('[') && line.contains(':') && !line.contains('=') && !trimmed.starts_with("inherit") {
        if let Some(colon_pos) = line.find(':') {
            let before_colon = line[..colon_pos].trim_end();
            if is_valid_ident(before_colon) && config.check_lambda_args && !before_colon.starts_with('_') {
                let col = find_position_in_line(line, before_colon);
                definitions.push((before_colon.to_string(), line_num, col, "lambda argument".to_string()));
            }
        }
    }

    // Pattern 2: Lambda pattern { args }@name or name@{ args }
    if line.contains('@') && line.contains('{') && line.contains('}') {
        extract_lambda_patterns(line, line_num, config, definitions);
    }

    // Pattern 3: Let binding: name = expr
    if line.contains(" = ") && !trimmed.starts_with("inherit") {
        if let Some(eq_pos) = line.find(" = ") {
            let before_eq = line[..eq_pos].trim();
            if is_valid_ident(before_eq) && !before_eq.contains('{') && !before_eq.contains('[') {
                if !before_eq.starts_with('_') || config.check_underscore {
                    let col = find_position_in_line(line, before_eq);
                    definitions.push((before_eq.to_string(), line_num, col, "let binding".to_string()));
                }
            }
        }
    }

    // Pattern 4: Inherit statement
    if trimmed.starts_with("inherit") {
        extract_inherit_definitions(line, line_num, config, definitions);
    }
}

fn extract_lambda_patterns(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    definitions: &mut Vec<(String, usize, usize, String)>,
) {
    if !config.check_lambda_pattern_names {
        return;
    }

    if let Some(at_pos) = line.find('@') {
        let first_brace = line.find('{');
        let first_closing = line.find('}');

        match (first_brace, first_closing) {
            (Some(brace_start), Some(brace_end)) if brace_start < brace_end => {
                let params_str = &line[brace_start + 1..brace_end];

                // Extract parameter names
                for param in params_str.split(',') {
                    let param_trim = param.trim();
                    if param_trim == "..." {
                        continue;
                    }

                    let name = param_trim.split('?').next().unwrap_or("").trim();
                    if !name.is_empty() && is_valid_ident(name) && !name.starts_with('_') {
                        let col = find_position_in_line(line, name);
                        definitions.push((name.to_string(), line_num, col, "lambda pattern".to_string()));
                    }
                }

                // Extract name before or after @
                if brace_start > at_pos {
                    // Format: name@{...}
                    let before_at = line[..at_pos].trim_end();
                    if is_valid_ident(before_at) && !before_at.starts_with('_') {
                        let col = find_position_in_line(line, before_at);
                        definitions.push((before_at.to_string(), line_num, col, "lambda pattern".to_string()));
                    }
                } else {
                    // Format: {...}@name
                    let after_at = line[at_pos + 1..].trim_start();
                    let name = after_at.split(':').next().unwrap_or("").split('{').next().unwrap_or("").trim();
                    if !name.is_empty() && name != "{" && is_valid_ident(name) && !name.starts_with('_') {
                        let col = find_position_in_line(line, name);
                        definitions.push((name.to_string(), line_num, col, "lambda pattern".to_string()));
                    }
                }
            }
            _ => {}
        }
    }
}

fn extract_inherit_definitions(
    line: &str,
    line_num: usize,
    config: &AnalysisConfig,
    definitions: &mut Vec<(String, usize, usize, String)>,
) {
    if let Some(_paren_start) = line.find('(') {
        if let Some(paren_end) = line.find(')') {
            let after_paren = &line[paren_end + 1..];
            for name in after_paren.split_whitespace() {
                let clean_name = name.trim_end_matches(';');
                if is_valid_ident(clean_name) {
                    if !clean_name.starts_with('_') || config.check_underscore {
                        let col = find_position_in_line(line, clean_name);
                        definitions.push((clean_name.to_string(), line_num, col, "let binding".to_string()));
                    }
                }
            }
        }
    }
}

fn collect_usages_from_line_smart(line: &str, usages: &mut HashSet<String>) {
    let trimmed = line.trim();
    if trimmed.starts_with('#') {
        return;
    }

    // Extract from computed keys: "${...}"  
    if line.contains("${") {
        let mut in_interp = false;
        let mut current_key = String::new();
        let mut chars = line.chars().peekable();
        while let Some(ch) = chars.next() {
            if ch == '$' && chars.peek() == Some(&'{') {
                chars.next(); // consume '{'
                in_interp = true;
                current_key.clear();
            } else if ch == '}' && in_interp {
                in_interp = false;
                extract_identifiers(&current_key, usages);
            } else if in_interp {
                current_key.push(ch);
            }
        }
    }

    // If there's an = sign, collect from the right side
    if let Some(eq_pos) = line.find(" = ") {
        let right_side = &line[eq_pos + 3..];
        extract_identifiers(right_side, usages);
    }

    // If there's a : (lambda) collect from the right side
    if line.contains(':') && !line.contains(" = ") {
        if let Some(colon_pos) = line.find(':') {
            let right_side = &line[colon_pos + 1..];
            extract_identifiers(right_side, usages);
        }
    }

    // Handle inherit statements - the things being inherited are marked as used
    if trimmed.starts_with("inherit") {
        if let Some(paren_start) = line.find('(') {
            if let Some(paren_end) = line.find(')') {
                let inside_parens = &line[paren_start + 1..paren_end];
                extract_identifiers(inside_parens, usages);
            }
        } else {
            // Simple inherit without parens
            let after_inherit = line.trim_start_matches("inherit").trim();
            extract_identifiers(after_inherit, usages);
        }
    }

    // Handle attribute access: x.y - x is being used
    if line.contains('.') {
        let mut current_word = String::new();
        for (char_idx, ch) in line.chars().enumerate() {
            if ch == '.' {
                if !current_word.is_empty() && is_valid_ident(&current_word) {
                    usages.insert(current_word.clone());
                }
                current_word.clear();
            } else if ch.is_alphanumeric() || ch == '_' || ch == '-' {
                current_word.push(ch);
            } else {
                if !current_word.is_empty() && is_valid_ident(&current_word) {
                    // Check if this is right before a .
                    if char_idx + 1 < line.len() && line.as_bytes()[char_idx + 1] as char == '.' {
                        usages.insert(current_word.clone());
                    }
                }
                current_word.clear();
            }
        }
    }
}

fn extract_identifiers(text: &str, usages: &mut HashSet<String>) {
    let mut current_word = String::new();

    for ch in text.chars() {
        if ch.is_alphanumeric() || ch == '_' || ch == '-' || ch == '\'' {
            current_word.push(ch);
        } else {
            if !current_word.is_empty() && is_valid_ident(&current_word) {
                usages.insert(current_word.clone());
            }
            current_word.clear();
        }
    }

    if !current_word.is_empty() && is_valid_ident(&current_word) {
        usages.insert(current_word);
    }
}

fn is_valid_ident(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }

    let first = s.chars().next().unwrap();
    if !first.is_alphabetic() && first != '_' {
        return false;
    }

    !matches!(s, "let" | "in" | "if" | "then" | "else" | "inherit" | "rec" | "with" | "assert" | "or" | "and" | "not")
}

fn find_position_in_line(line: &str, needle: &str) -> usize {
